const legacyWordIdMap=new Map(words.map(w=>[w.legacyId,w.id]));
function migrateProgressKeys(raw){const input=raw&&typeof raw==='object'?raw:{};const out={};for(const [id,value] of Object.entries(input)){if(wordIdSet.has(id)&&value&&typeof value==='object')out[id]=value;}for(const [id,value] of Object.entries(input)){const mapped=legacyWordIdMap.get(id);if(mapped&&!out[mapped]&&value&&typeof value==='object')out[mapped]=value;}return out;}
const TOPIC_EN={'飲食與餐廳':'Food & restaurants','購物與付款':'Shopping & payments','交通與旅行':'Transport & travel','居家生活':'Home life','健康與醫療':'Health & medicine','工作與學習':'Work & study','人際與情緒':'Relationships & emotions','科技與通訊':'Technology & communication','天氣與戶外':'Weather & outdoors','休閒與動作':'Leisure & actions','公共服務與地點':'Public services & places','常用口語表達':'Common spoken expressions'};
