const CURRICULUM_STAGES=[
 {name:'準備起步',en:'Getting started',goal:'熟悉高實用度詞彙，建立基本聲音、詞義與簡短表達。',goalEn:'Build familiarity with useful words, sounds, meanings, and short expressions.'},
 {name:'初級開口',en:'First conversations',goal:'練習簡短問答與常見生活需求，開始把詞彙放進句子。',goalEn:'Practise short exchanges and everyday needs with words in simple sentences.'},
 {name:'生活入門',en:'Everyday basics',goal:'在熟悉情境中辨認關鍵資訊，完成簡單的生活任務。',goalEn:'Recognise key information and complete simple everyday tasks.'},
 {name:'基礎溝通',en:'Basic communication',goal:'延伸句型與搭配詞，讓日常對話更完整。',goalEn:'Expand patterns and collocations for more complete everyday exchanges.'},
 {name:'中級表達',en:'Connected expression',goal:'說明偏好、經驗、原因與安排，練習連貫表達。',goalEn:'Explain preferences, experiences, reasons, and plans coherently.'},
 {name:'進階互動',en:'Advanced interaction',goal:'處理較複雜的情境，練習協商、澄清與提出建議。',goalEn:'Handle more complex situations, clarification, negotiation, and suggestions.'},
 {name:'流利運用',en:'Fluent use',goal:'提升語意精準度、語體選擇與較長內容的理解。',goalEn:'Improve precision, register choices, and understanding of longer content.'},
 {name:'精熟運用',en:'Refined mastery',goal:'運用細緻詞義與複雜表達，靈活處理不同溝通目的。',goalEn:'Use nuanced meanings and complex expressions for varied communication goals.'}
];
const CURRICULUM_UNIT_SIZE=8;
const lessons=[];
CURRICULUM_TOPICS.forEach((topic,topicIndex)=>{
 const group=words.filter(w=>w.topic===topic).slice().sort((a,b)=>{
  const sa=a.estimatedDifficulty*18+(100-a.priorityScore)*0.35-a.utilityScore*1.5-a.commonScore*0.08;
  const sb=b.estimatedDifficulty*18+(100-b.priorityScore)*0.35-b.utilityScore*1.5-b.commonScore*0.08;
  return sa-sb||b.priorityScore-a.priorityScore||b.utilityScore-a.utilityScore||a.zh.localeCompare(b.zh,'zh-Hant');
 });
 const bucketSize=Math.ceil(group.length/CURRICULUM_STAGES.length);
 CURRICULUM_STAGES.forEach((stage,stageIndex)=>{
  const band=group.slice(stageIndex*bucketSize,stageIndex===CURRICULUM_STAGES.length-1?group.length:Math.min(group.length,(stageIndex+1)*bucketSize));
  band.forEach(w=>{w.courseStage=stageIndex;});
  for(let start=0;start<band.length;start+=CURRICULUM_UNIT_SIZE){
   const part=band.slice(start,start+CURRICULUM_UNIT_SIZE),unitNo=Math.floor(start/CURRICULUM_UNIT_SIZE)+1;
   const id=`course-${stageIndex+1}-${String(topicIndex+1).padStart(2,'0')}-${String(unitNo).padStart(2,'0')}`;
   const wordIds=part.map(w=>w.id);
   const title=`${stage.name}｜${topic}｜第 ${unitNo} 單元`;
   const en=`${stage.en} · ${TOPIC_EN[topic]||topic} · Unit ${unitNo}`;
   const desc=`本單元包含 ${part.length} 個詞條，依教學難度估計、學習優先度與實用度作平台內部排序。`;
   const descEn=`${part.length} vocabulary items arranged using internal teaching estimates, priority, and utility.`;
   const searchText=[title,en,desc,...part.flatMap(w=>[w.zh,w.py,w.en,w.ex,w.exen])].join(' ').toLowerCase();
   lessons.push({id,title,en,desc,descEn,icon:TOPIC_ICONS[topicIndex%TOPIC_ICONS.length],art:TOPIC_ARTS[topicIndex%TOPIC_ARTS.length],words:wordIds,duration:`${Math.max(5,part.length*1.2|0)} min`,topic,topicIndex,stageIndex,unitNo,searchText});
  }
 });
});
