function renderI18n(){document.documentElement.lang=state.ui==='en'?'en':'zh-Hant';document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n,val=String(t(key));if(val.includes('<br>'))el.innerHTML=val;else el.textContent=val;el.classList.toggle('langline',val.includes('\n'))});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));$('uiLanguage').value=state.ui;$('settingsLanguage').value=state.ui;$('goalSelect').value=String(state.goal);$('settingsGoal').value=String(state.goal);$('profileName').value=state.profile;$('vocabSearch').placeholder=t('search_placeholder');renderAll();if(state.quiz)renderQuiz();const flashView=$('view-flashcards');if(flashView&&flashView.classList.contains('active'))renderFlashcard();const active=document.querySelector('.view.active');setPageTitle(active?active.id.replace('view-',''):'home');renderStrokeOrderLanguage()}
function syncDuplicatePageHeading(){const titleEl=$('pageTitle');const active=document.querySelector('.view.active');if(!titleEl||!active)return;const normalizeTitle=value=>String(value||'').normalize('NFKC').toLocaleLowerCase().replace(/[\s·•|:：,，。.!！?？]/g,'');const current=normalizeTitle(titleEl.innerText||titleEl.textContent);active.querySelectorAll('.page-intro h2').forEach(heading=>{const headingText=normalizeTitle(heading.innerText||heading.textContent);heading.classList.toggle('duplicate-page-title',Boolean(current)&&headingText===current);});}
