async function exportCoreAudioPack(){try{const rows=await AudioEngine.storage.all('core');if(!rows.length){toast(t('audio_export_none'));return;}const assets=[];for(const row of rows){if(!row.blob)continue;const bytes=new Uint8Array(await row.blob.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,Math.min(i+0x8000,bytes.length)));assets.push({symbol:row.symbol||row.key,fileName:row.fileName||'',mime:row.mime||row.blob.type||'application/octet-stream',license:row.license||'Unverified',source:row.source||'User-provided audio',attribution:row.attribution||'License not verified',addedAt:row.addedAt||'',dataBase64:btoa(binary)});}const payload={app:'TaiwanMandarinCoreAudio',schema:1,createdAt:new Date().toISOString(),attribution:'Ministry of Education, R.O.C. (Taiwan), The Manual of the Phonetic Symbols of Mandarin Chinese; related audio assets are identified by the official page as CC BY 4.0 when sourced from that package.',assets};const blob=new Blob([JSON.stringify(payload)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='taiwan-mandarin-core-audio-'+today()+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast(t('audio_export_done').replace('{n}',String(assets.length)))}catch(e){toast(t('audio_engine_error'))}}
async function importCoreAudioPack(file){if(!file)return;try{if(file.size>100*1024*1024)throw Error('too large');const data=JSON.parse(await file.text());if(data.app!=='TaiwanMandarinCoreAudio'||data.schema!==1||!Array.isArray(data.assets)||data.assets.length>37)throw Error('schema');let n=0;for(const asset of data.assets){if(!asset||!CORE_AUDIO_SYMBOLS.includes(asset.symbol)||typeof asset.dataBase64!=='string'||asset.dataBase64.length>40*1024*1024)continue;const binary=atob(asset.dataBase64);const bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);const blob=new Blob([bytes],{type:asset.mime||'application/octet-stream'});if(!blob.size)continue;await AudioEngine.storage.put('core',{key:asset.symbol,symbol:asset.symbol,blob,fileName:String(asset.fileName||'restored-audio').slice(0,180),mime:blob.type,license:String(asset.license||'Unverified'),source:String(asset.source||'User-provided audio'),attribution:String(asset.attribution||'License not verified'),addedAt:String(asset.addedAt||new Date().toISOString())});n++;}await refreshCoreAudioStatus();toast(t('audio_import_pack_done').replace('{n}',String(n)))}catch(e){toast(t('audio_import_pack_invalid'))}finally{const input=$('importCoreAudioPack');if(input)input.value=''}}
function renderCoreAudioMapping(){const el=$('coreAudioMapping');if(!el)return;const files=audioImportFiles;const current={};el.querySelectorAll('select[data-symbol]').forEach(sel=>current[sel.dataset.symbol]=sel.value);el.innerHTML=CORE_AUDIO_SYMBOLS.map(sym=>{const opts=['<option value="">'+safe(t('audio_file_unassigned'))+'</option>'].concat(files.map((f,i)=>`<option value="${i}">${safe(f.name)} (${Math.max(1,Math.round(f.size/1024))} KB)</option>`));const prior=current[sym]??String(files.findIndex(f=>guessCoreSymbol(f.name)===sym));const selected=prior!==''&&Number(prior)>=0&&Number(prior)<files.length?Number(prior):'';return `<div class="core-audio-map-row"><div class="core-audio-symbol">${safe(sym)}</div><select data-symbol="${safe(sym)}" aria-label="${safe(t('audio_select_symbol_file'))} ${safe(sym)}">${opts.map((o,i)=>{if(i===0)return o;const idx=i-1;return `<option value="${idx}" ${String(idx)===String(selected)?'selected':''}>${safe(files[idx].name)} (${Math.max(1,Math.round(files[idx].size/1024))} KB)</option>`}).join('')}</select><button type="button" class="btn btn-line" onclick="previewCoreAudioFileForSymbol('${sym}')">▶ ${safe(t('audio_preview'))}</button></div>`}).join('');if(!files.length)el.innerHTML=`<p class="muted tiny" style="padding:12px;margin:0">${safe(t('audio_no_files'))}</p>`}
function previewCoreAudioFileForSymbol(symbol){const sel=$(`coreAudioMapping`)?.querySelector(`select[data-symbol="${CSS.escape(symbol)}"]`);if(!sel||sel.value==='')return;const file=audioImportFiles[Number(sel.value)];if(file)AudioEngine.previewFile(file)}
async function refreshCoreAudioStatus(){const status=$('audioEngineStatus'),count=$('coreAudioCount');try{const st=await AudioEngine.status();if(count)count.textContent=`${st.coreCount} / ${CORE_AUDIO_SYMBOLS.length}`;if(status){status.classList.toggle('warn',!st.synth||st.coreCount<CORE_AUDIO_SYMBOLS.length);status.classList.remove('error');status.textContent=st.synth?t('audio_engine_ready').replace('{n}',String(st.coreCount)):t('audio_engine_no_synth');if(!st.idb)status.textContent+=' '+t('audio_engine_store_unavailable')}}catch(e){if(status){status.classList.add('error');status.textContent=t('audio_engine_error')}}}
async function handleCoreAudioFilesChange(event){audioImportFiles=Array.from(event.target.files||[]).filter(f=>f&&(f.type.startsWith('audio/')||/\.(mp3|wav|ogg|m4a|aac|webm|opus|flac)$/i.test(f.name)));renderCoreAudioMapping();if(!audioImportFiles.length)toast(t('audio_no_files'));else toast(`${audioImportFiles.length} ${state.ui==='en'?'audio files ready':state.ui==='bi'?'個音檔已就緒\nAudio files ready':'個音檔已就緒'}`)}
async function importCoreAudioMappings(){const el=$('coreAudioMapping');if(!el)return;const mappings={};const used=new Set();el.querySelectorAll('select[data-symbol]').forEach(sel=>{if(sel.value!==''&&!used.has(String(sel.value))){mappings[sel.dataset.symbol]=sel.value;used.add(String(sel.value))}});if(!Object.keys(mappings).length){toast(t('audio_import_none'));return}const confirmed=!!$('audioMoeLicenseConfirmed')?.checked;if(!confirmed){toast(t('audio_import_license_warning'));}try{const n=await AudioEngine.importCoreMappings(audioImportFiles,mappings,confirmed);await refreshCoreAudioStatus();toast(t('audio_import_success').replace('{n}',String(n)))}catch(e){toast(t('audio_engine_error'))}}
