$('vocabSearch').addEventListener('input',renderVocab);$('topicFilter').addEventListener('change',renderVocab);function toggleKnown(id){const p=wordProgress(id);p.known=!p.known;if(p.known){p.seen=Math.max(1,p.seen);p.last=today()}save();renderVocab();renderStats();renderCurriculum();toast(p.known?t('known'):t('review'))}
let voices=[];
// Restore the voice-list renderer required by renderAll() during startup.
// Keep this function safe: a missing/blocked speech engine must never interrupt app initialization.
function voiceRank(v){
 const lang=String(v.lang||'').replace(/_/g,'-').toLowerCase();
 const name=String(v.name||'').toLowerCase();let score=0;
 if(lang==='zh-tw')score+=100;else if(lang.startsWith('zh-tw-'))score+=95;else if(lang==='zh-hant'||lang.startsWith('zh-hant-'))score+=82;else if(lang==='zh-hk'||lang.startsWith('zh-hk-'))score+=55;else if(lang.startsWith('zh'))score+=25;
 if(/natural|neural|online|premium/.test(name))score+=18;
 if(/google.*台灣|google.*taiwan|yating|hanhan|zhiwei|hsiaochen|xiaoyu/.test(name))score+=15;
 if(/desktop|compact|legacy|espeak/.test(name))score-=8;
 return score;
}
function updateVoiceQualityNote(){
 const note=$('speechVoiceQualityNote');if(!note)return;
 const selected=state.voice&&state.voice!=='auto'?voices.find(v=>v.name===state.voice):null;
 const isTaiwan=v=>/^zh[-_]tw(?:[-_]|$)/i.test(String(v?.lang||''))||/taiwan|台灣|yating|hanhan|zhiwei|hsiaochen/i.test(String(v?.name||''));
 const taiwanAvailable=voices.some(isTaiwan);
 note.textContent=t(taiwanAvailable?'voice_quality_tw_available':'voice_quality_no_tw');
 if(selected&&!isTaiwan(selected))note.textContent=(state.ui==='en'?`Selected voice: ${selected.name} (${selected.lang}). This may not use Taiwan Mandarin pronunciation.`:state.ui==='bi'?`目前選擇：${selected.name}（${selected.lang}），口音可能不是台灣華語。\nSelected voice: ${selected.name} (${selected.lang}); the accent may not be Taiwan Mandarin.`:`目前選擇：${selected.name}（${selected.lang}），口音可能不是台灣華語。`);
 note.classList.toggle('error',!taiwanAvailable||(selected&&!isTaiwan(selected)));
}
function renderVoiceList(){
 const select=$('voiceSelect');if(!select)return;
 const old=state.voice||'auto';
 try{voices=('speechSynthesis'in window)?(window.speechSynthesis.getVoices()||[]):[]}catch(e){voices=[];}
 voices.sort((a,b)=>voiceRank(b)-voiceRank(a));
 const autoLabel=state.ui==='en'?'Auto-select best available Taiwan Mandarin voice':state.ui==='bi'?'自動選擇台灣華語語音\nAuto-select Taiwan Mandarin voice':'自動選擇台灣華語語音';
 select.innerHTML='';const autoOption=document.createElement('option');autoOption.value='auto';autoOption.textContent=autoLabel;select.appendChild(autoOption);
 voices.filter(v=>/^zh/i.test(String(v.lang||''))).forEach(v=>{const option=document.createElement('option');option.value=v.name;option.textContent=`${v.name} (${v.lang})`;select.appendChild(option)});
 select.value=old;if(select.value!==old){select.value='auto';state.voice='auto';}
 updateVoiceQualityNote();
}
