function getMandarinVoice(){
 if(!('speechSynthesis'in window))return null;
 voices=window.speechSynthesis.getVoices()||[];
 if(state.voice&&state.voice!=='auto'){const chosen=voices.find(v=>v.name===state.voice);if(chosen)return chosen;}
 const candidates=voices.filter(v=>/^zh/i.test(String(v.lang||''))).sort((a,b)=>voiceRank(b)-voiceRank(a));
 return candidates[0]||null;
}
function normalizeSpeechRate(value){const n=Number(value);return [0.65,0.82,0.95,1.1].includes(n)?n:0.82;}
// Central audio engine: shared by vocabulary, lessons, flashcards, Zhuyin and examples.
const AudioStorage = (()=>{
 let dbPromise=null;const mem={core:new Map(),tts:new Map()};
 function open(){
  if(!('indexedDB'in window))return Promise.reject(new Error('indexedDB unavailable'));
  if(dbPromise)return dbPromise;
  dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('taiwanMandarinAudio_v18',1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('core'))db.createObjectStore('core',{keyPath:'key'});if(!db.objectStoreNames.contains('tts'))db.createObjectStore('tts',{keyPath:'key'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('open failed'));req.onblocked=()=>reject(new Error('database blocked'));});
  return dbPromise;
 }
 async function get(store,key){try{const db=await open();return await new Promise((resolve,reject)=>{const tx=db.transaction(store,'readonly'),req=tx.objectStore(store).get(key);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);});}catch(e){return mem[store==='core'?'core':'tts'].get(key)||null}}
 async function put(store,obj){try{const db=await open();await new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).put(obj);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('transaction aborted'));});return true;}catch(e){mem[store==='core'?'core':'tts'].set(obj.key,obj);return false}}
 async function all(store){try{const db=await open();return await new Promise((resolve,reject)=>{const tx=db.transaction(store,'readonly'),req=tx.objectStore(store).getAll();req.onsuccess=()=>resolve(req.result||[]);req.onerror=()=>reject(req.error);});}catch(e){return [...mem[store==='core'?'core':'tts'].values()]}}
 async function del(store,key){try{const db=await open();await new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');tx.objectStore(store).delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}catch(e){mem[store==='core'?'core':'tts'].delete(key)}}
 return {open,get,put,all,del,hasIndexedDB:()=>('indexedDB'in window)};
})();
const AudioEngine = (()=>{
 let generation=0, currentAudio=null, currentObjectUrl=null, currentUtterance=null;
 const rate=()=>normalizeSpeechRate(state.speechRate);
 function message(text){try{toast(text)}catch(e){}}
 function stop(){generation++;try{window.speechSynthesis?.cancel()}catch(e){};if(currentAudio){try{currentAudio.pause();currentAudio.currentTime=0}catch(e){};currentAudio=null;}if(currentObjectUrl){URL.revokeObjectURL(currentObjectUrl);currentObjectUrl=null;}currentUtterance=null;}
 function pause(){if(currentAudio&&!currentAudio.paused)currentAudio.pause();else if(currentUtterance&&window.speechSynthesis?.speaking)window.speechSynthesis.pause();}
 function resume(){if(currentAudio&&currentAudio.paused)currentAudio.play().catch(()=>{});else if(window.speechSynthesis?.paused)window.speechSynthesis.resume();}
 function hash(value){let h=2166136261;for(let i=0;i<value.length;i++){h^=value.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16)}
 function ttsKey(text){return hash([String(text),String(state.audioVoiceId||''),String(rate()),String(state.audioEndpointUrl||''),'tts-contract-v2'].join('\u001f'))}
 async function playBlob(blob,token,playbackRate=1){if(!blob||token!==generation)return false;stop();const ownToken=++generation;try{currentObjectUrl=URL.createObjectURL(blob);currentAudio=new Audio(currentObjectUrl);currentAudio.playbackRate=Number.isFinite(Number(playbackRate))?Math.max(0.5,Math.min(2,Number(playbackRate))):1;currentAudio.onended=()=>{if(ownToken===generation){try{URL.revokeObjectURL(currentObjectUrl)}catch(e){}currentAudio=null;currentObjectUrl=null}};currentAudio.onerror=()=>{if(ownToken===generation)message(t('audio_preview_failed'));};await currentAudio.play();return true}catch(e){if(currentObjectUrl)URL.revokeObjectURL(currentObjectUrl);currentObjectUrl=null;currentAudio=null;return false}}
 function speakLocal(text,token){if(token!==generation)return false;if(!('speechSynthesis'in window)||typeof SpeechSynthesisUtterance==='undefined'){message(t('voice_unavailable'));return false;}try{const synth=window.speechSynthesis;synth.cancel();const u=new SpeechSynthesisUtterance(String(text||''));u.lang='zh-TW';u.rate=rate();u.pitch=1;u.volume=1;const v=getMandarinVoice();if(v)u.voice=v;currentUtterance=u;u.onend=()=>{if(currentUtterance===u)currentUtterance=null};u.onerror=(ev)=>{if(currentUtterance===u)currentUtterance=null;if(ev?.error!=='canceled'&&ev?.error!=='interrupted')message(t('voice_unavailable'))};window.setTimeout(()=>{if(token===generation){try{synth.speak(u)}catch(e){message(t('voice_unavailable'))}}},70);return true}catch(e){message(t('voice_unavailable'));return false}}
 async function requestNeural(text,token){const endpoint=String(state.audioEndpointUrl||'').trim();if(!endpoint||!navigator.onLine)return null;let u;try{u=new URL(endpoint,location.href)}catch(e){return null}if(!(u.protocol==='https:'||(u.protocol==='http:'&&['localhost','127.0.0.1','::1'].includes(u.hostname))))return null;const key=ttsKey(text);const cached=await AudioStorage.get('tts',key);if(cached?.blob&&token===generation)return {blob:cached.blob,rateApplied:!!cached.rateApplied};const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','Accept':'audio/mpeg,audio/wav,application/octet-stream,application/json'},body:JSON.stringify({text:String(text),locale:'cmn-TW',voiceId:state.audioVoiceId||'',rate:rate()}),signal:controller.signal,credentials:'omit',referrerPolicy:'strict-origin-when-cross-origin'});if(!response.ok)throw new Error('TTS HTTP '+response.status);let blob;const ct=(response.headers.get('content-type')||'').toLowerCase();if(ct.includes('application/json')){const j=await response.json();if(typeof j.audioBase64!=='string')throw new Error('TTS JSON must include audioBase64');const mime=j.mimeType||'audio/mpeg';const binary=atob(j.audioBase64);const bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);blob=new Blob([bytes],{type:mime})}else{blob=await response.blob();if(!/^audio\//.test(blob.type||ct)&&!ct.includes('octet-stream'))throw new Error('Unexpected TTS content type')}if(!blob.size)throw new Error('Empty TTS audio');const rateApplied=response.headers.get('x-tts-rate-applied')==='true';await AudioStorage.put('tts',{key,blob,createdAt:Date.now(),mime:blob.type||ct,rateApplied});return {blob,rateApplied}}catch(e){return null}finally{clearTimeout(timer)}}
 async function speak(text){const target=String(text||'').trim();if(!target)return false;stop();const token=generation;try{const result=await requestNeural(target,token);if(result?.blob&&token===generation){const ok=await playBlob(result.blob,token,result.rateApplied?1:rate());if(ok)return true;}}catch(e){}if(token!==generation)return false;return speakLocal(target,token)}
 async function testNeural(text){const target=String(text||'').trim();if(!target)return false;stop();const token=generation;const result=await requestNeural(target,token);if(!result?.blob||token!==generation)return false;return playBlob(result.blob,token,result.rateApplied?1:rate())}
 async function playCoreSymbol(symbol){const s=String(symbol||'').trim();if(!s)return false;stop();const token=generation;const item=await AudioStorage.get('core',s);if(token!==generation)return false;if(item?.blob){const ok=await playBlob(item.blob,token,rate());if(ok)return true;}message(t('audio_symbol_missing'));return false}
 async function previewFile(file){if(!file)return false;stop();const token=generation;return playBlob(file,token)}
 async function importCoreMappings(files,mappings,verifiedMOE){let count=0;for(const [symbol,index] of Object.entries(mappings)){const file=files[Number(index)];if(!file||!String(symbol))continue;await AudioStorage.put('core',{key:symbol,symbol,blob:file,fileName:file.name||'audio',mime:file.type||'application/octet-stream',source:verifiedMOE?'Ministry of Education, The Manual of the Phonetic Symbols of Mandarin Chinese':'User-provided audio',license:verifiedMOE?'CC BY 4.0':'Unverified',attribution:verifiedMOE?'Ministry of Education, R.O.C. (Taiwan), The Manual of the Phonetic Symbols of Mandarin Chinese, CC BY 4.0':'License not verified',addedAt:new Date().toISOString()});count++;}return count}
 async function status(){const records=await AudioStorage.all('core');let idb=false;try{await AudioStorage.open();idb=true}catch(e){}return {coreCount:records.length,coreSymbols:records.map(x=>x.key),idb,synth:('speechSynthesis'in window)&&typeof SpeechSynthesisUtterance!=='undefined',endpoint:!!String(state.audioEndpointUrl||'').trim()}}
 return {speak,testNeural,stop,pause,resume,playCoreSymbol,previewFile,importCoreMappings,status,storage:AudioStorage};
})();
window.AudioEngine=AudioEngine;
function speakMandarin(text){return AudioEngine.speak(text)}
function playCoreSymbol(symbol){return AudioEngine.playCoreSymbol(symbol)}
window.playCoreSymbol=playCoreSymbol;
