// Expanded practice bank: 5,000 generated question variants based on the app's vocabulary.
// Variants rotate between character-to-English, character-to-pinyin, and English-to-character,
// with varied distractor sets. This is a reusable local bank; it does not require an API.
let expandedQuestionBank=null;
function buildExpandedQuestionBank(){
 if(expandedQuestionBank)return expandedQuestionBank;
 const bank=[],types=['en','py','zh'],n=words.length;
 if(!n)return [];
 for(let i=0;i<5000;i++){
  const wi=(i*37+Math.floor(i/11)*13)%n,w=words[wi],type=types[i%3],distractors=[],seen=new Set([w.id]);
  let seed=(i*17+Math.floor(i/7)*19+3)%n,tries=0;
  while(distractors.length<3&&tries<n*3){
   const candidate=words[(seed+tries*7+Math.floor(tries/Math.max(1,n))*11)%n];
   if(candidate&&!seen.has(candidate.id)){seen.add(candidate.id);distractors.push(candidate)}
   tries++;
  }
  // If the vocabulary list is unusually small, safely fill remaining choices.
  while(distractors.length<3)distractors.push(w);
  const choiceWords=[w,...distractors];
  for(let j=choiceWords.length-1;j>0;j--){const k=(i*13+j*7+Math.floor(i/5))%(j+1);[choiceWords[j],choiceWords[k]]=[choiceWords[k],choiceWords[j]]}
  bank.push({qid:'q'+String(i+1).padStart(4,'0'),id:w.id,type,choices:choiceWords.map(x=>({id:x.id,label:type==='en'?x.en:type==='py'?x.py:x.zh})),answer:w.id,category:type==='en'?'詞義':type==='py'?'拼音':'辨字'});
 }
 return expandedQuestionBank=bank;
}
function startExpandedQuiz(){
 state.quizLength=Math.max(5,Math.min(5000,Number($('quizLength')?.value)||10));
 state.quizMode=$('quizMode')?.value||'mixed';
 const bank=buildExpandedQuestionBank().filter(q=>state.quizMode==='mixed'||q.type===state.quizMode);
 const picked=bank.slice().sort(()=>Math.random()-.5).slice(0,Math.min(state.quizLength,bank.length));
 state.quiz={pool:words,index:0,questions:picked,answers:[],selected:null,checked:false,reviewOnly:false};
 renderQuiz();
}

function startQuiz(reviewOnly=false){const pool=reviewOnly?words.filter(w=>{const p=wordProgress(w.id);return !!p.review||!!(p.due&&p.due<=today())}):words.slice();if(!pool.length){state.quiz={pool:[],index:0,questions:[],answers:[],reviewOnly};renderQuiz();return}const shuffled=pool.slice().sort(()=>Math.random()-.5).slice(0,Math.min(state.quizLength||10,pool.length));const questions=shuffled.map((w,i)=>{const types=['en','py','zh'];const type=(!state.quizMode||state.quizMode==='mixed')?types[Math.floor(Math.random()*types.length)]:state.quizMode;const distractors=words.filter(x=>x.id!==w.id).sort(()=>Math.random()-.5).slice(0,3);const choices=[w,...distractors].sort(()=>Math.random()-.5);return {id:w.id,type,choices:choices.map(x=>({id:x.id,label:type==='en'?x.en:type==='py'?x.py:x.zh})),answer:w.id}});state.quiz={pool,index:0,questions,answers:[],selected:null,checked:false,reviewOnly};renderQuiz()}
function renderQuiz(){const qz=state.quiz;if(!qz){$('quizCard').innerHTML='';return}if(!qz.questions.length){$('quizCard').innerHTML=`<div class="empty">${t('no_review')}<br><br><button class="btn btn-green" onclick="startQuiz(false)">${t('restart_quiz')}</button></div>`;return}if(qz.index>=qz.questions.length){const score=qz.answers.filter(a=>a.correct).length;const total=qz.questions.length;if(!qz.resultSaved){const item={date:today(),score,total,reviewOnly:qz.reviewOnly};state.history.push(item);state.history=state.history.slice(-300);activity({kind:'quiz',score,total});save();qz.resultSaved=true;}$('quizCard').innerHTML=`<div style="text-align:center;padding:20px 0"><div style="font-size:45px">${score===total?'🎉':'🌱'}</div><h2 style="font-size:27px;margin:18px 0 7px">${t('quiz_complete')}</h2><p class="muted" style="font-size:12px">${t('score')}: ${score} / ${total} · ${t('accuracy')} ${Math.round(score/total*100)}%</p><div class="bar" style="margin:25px 0"><span style="width:${score/total*100}%;background:var(--green)"></span></div><button class="btn btn-green" onclick="startQuiz(${qz.reviewOnly?'true':'false'})">${t('restart_quiz')}</button> <button class="btn btn-line" onclick="go('review')">${t('review_title')}</button></div>`;renderStats();renderHomeLessons();return}const q=qz.questions[qz.index],w=words.find(x=>x.id===q.id);const prompt=q.type==='en'?t('quiz_intro'):q.type==='py'?t('quiz_intro_py'):t('quiz_intro_zh');const target=q.type==='en'?w.zh:q.type==='py'?w.zh:w.en;const sub=q.type==='en'?w.py:q.type==='py'?w.en:t('meaning');$('quizCard').innerHTML=`<div class="quiz-top"><span>${t('question')} ${qz.index+1} / ${qz.questions.length}</span><span>${qz.reviewOnly?t('review_title'):t('practice_title')}</span></div><div class="step-line"><span style="width:${qz.index/qz.questions.length*100}%"></span></div><div class="question">${target}</div><div class="question-sub">${prompt} · ${sub}</div><div class="answers">${q.choices.map((c,i)=>`<button class="answer ${qz.checked?(c.id===q.answer?'correct':c.id===qz.selected?'wrong':''):qz.selected===c.id?'selected':''}" ${qz.checked?'disabled':''} onclick="selectAnswer('${c.id}')"><span class="letter">${String.fromCharCode(65+i)}</span><span>${safe(c.label)}</span></button>`).join('')}</div>${qz.checked?`<div class="feedback" style="color:${qz.selected===q.answer?'var(--green)':'var(--red)'}">${qz.selected===q.answer?t('correct'):t('incorrect')} ${safe(w.zh)} · ${safe(w.py)} · ${safe(w.en)}</div>`:''}<div class="quiz-footer"><span class="muted tiny">${qz.answers.filter(a=>a.correct).length} ${t('correct')}</span>${qz.checked?`<button class="btn btn-green" onclick="nextQuestion()">${qz.index===qz.questions.length-1?t('done'):t('next_question')} →</button>`:`<button class="btn btn-green" onclick="checkAnswer()" ${qz.selected?'':'disabled'}>${t('check_answer')}</button>`}</div>`}
function selectAnswer(id){if(!state.quiz||state.quiz.checked)return;state.quiz.selected=id;renderQuiz()}function checkAnswer(){const qz=state.quiz,q=qz.questions[qz.index];if(!qz.selected)return;const correct=qz.selected===q.answer;qz.checked=true;qz.answers.push({id:q.id,correct});const p=wordProgress(q.id);if(correct){p.correct++;p.streak++;p.last=today();p.due=addDays(today(),p.streak>=4?7:p.streak>=2?3:1);p.review=false;if(p.streak>=3)p.known=true;}else{p.wrong++;p.streak=0;p.due=today();p.review=true;p.known=false;}save();renderQuiz();renderReview();renderVocab();renderCurriculum()}function nextQuestion(){if(!state.quiz)return;state.quiz.index++;state.quiz.selected=null;state.quiz.checked=false;renderQuiz()}
function renderReview(){const list=words.filter(w=>{const p=wordProgress(w.id);return p.review||p.wrong>0});$('reviewCount').textContent=list.length;$('reviewList').innerHTML=list.length?list.map(w=>`<div class="word-row"><div class="hanzi">${w.zh}</div><div class="word-info"><b>${w.en}</b><small>${w.py} · ${w.ex}</small></div><span class="pill">${wordProgress(w.id).wrong} ${t('incorrect').replace('！','')}</span><button class="round-btn" onclick="speak('${w.id}')">🔊</button><button class="round-btn" onclick="toggleReview('${w.id}')">✓</button></div>`).join(''):`<div class="empty">${t('no_review')}</div>`}
function toggleReview(id){const p=wordProgress(id);p.review=!p.review;if(!p.review&&p.wrong===0)p.known=true;save();renderReview();renderHomeLessons()}
function renderProgress(){if($('extraReadingCount'))$('extraReadingCount').textContent=extraState.reading||0;if($('extraGrammarCount'))$('extraGrammarCount').textContent=extraState.grammar||0;if($('extraListeningCount'))$('extraListeningCount').textContent=extraState.listening||0;if($('extraExamCount'))$('extraExamCount').textContent=extraState.examHistory?.length||0;if(!$('activityList'))return;const list=state.activities.slice(0,12);$('activityList').innerHTML=list.length?list.map(a=>`<div class="word-row"><div class="stat-icon">✓</div><div class="word-info"><b>${safe(a.text)}</b><small>${safe(a.date)}</small></div></div>`).join(''):`<div class="empty">${t('no_activity')}</div>`}
function saveSettings(){state.ui=$('settingsLanguage').value;state.goal=+$('settingsGoal').value;state.profile=$('profileName').value.trim()||'Learner';state.voice=$('voiceSelect').value||'auto';state.speechRate=normalizeSpeechRate($('speechRateSelect')?.value??state.speechRate);save();renderI18n();toast(t('saved'))}
$('uiLanguage').addEventListener('change',e=>{state.ui=e.target.value;save();renderI18n()});$('settingsLanguage').addEventListener('change',e=>{state.ui=e.target.value;$('uiLanguage').value=state.ui;save();renderI18n()});$('goalSelect').addEventListener('change',e=>{state.goal=+e.target.value;save();renderStats()});$('settingsGoal').addEventListener('change',e=>{$('goalSelect').value=e.target.value});$('voiceSelect').addEventListener('change',e=>{state.voice=e.target.value;save();updateVoiceQualityNote()});
