$('saveAudioEndpoint')?.addEventListener('click',()=>{const raw=String($('audioEndpointUrl')?.value||'').trim();if(raw){let u;try{u=new URL(raw)}catch(e){toast(t('audio_endpoint_invalid'));return}if(!(u.protocol==='https:'||(u.protocol==='http:'&&['localhost','127.0.0.1','::1'].includes(u.hostname)))){toast(t('audio_endpoint_invalid'));return}}state.audioEndpointUrl=raw;save();refreshCoreAudioStatus();toast(t('audio_endpoint_saved'))});
$('clearAudioEndpoint')?.addEventListener('click',()=>{state.audioEndpointUrl='';if($('audioEndpointUrl'))$('audioEndpointUrl').value='';save();refreshCoreAudioStatus();toast(t('audio_endpoint_saved'))});
$('coreAudioFiles')?.addEventListener('change',handleCoreAudioFilesChange);
$('importCoreAudio')?.addEventListener('click',importCoreAudioMappings);
