function exportData(){const data={app:'TaiwanMandarinLearning',schema:1,exportedAt:new Date().toISOString(),settings:{ui:state.ui,goal:state.goal,profile:state.profile,voice:state.voice,speechRate:state.speechRate||0.82,theme:state.theme||'light',audioEndpointUrl:state.audioEndpointUrl||'',audioVoiceId:state.audioVoiceId||''},zhuyinStats:zhuyinStats,progress:state.progress,history:state.history,minutesByDay:state.minutesByDay,activities:state.activities,courseProgress:state.courseProgress,extraLearning:extraState};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='taiwan-mandarin-backup-'+today()+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('exported'))}
$('importFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('too large');const data=JSON.parse(await file.text());if(data.app!=='TaiwanMandarinLearning'||data.schema!==1||!data.progress||typeof data.progress!=='object'||!Array.isArray(data.history))throw Error('schema');if(data.zhuyinStats&&typeof data.zhuyinStats==='object'){zhuyinStats={attempts:Math.max(0,Number(data.zhuyinStats.attempts)||0),correct:Math.max(0,Number(data.zhuyinStats.correct)||0)};saveZhuyinStats()}const cleanProgress={};const importedProgress=migrateProgressKeys(data.progress);for(const [id,p] of Object.entries(importedProgress)){if(wordIdSet.has(id)&&p&&typeof p==='object')cleanProgress[id]={...p,seen:Math.max(0,Number(p.seen)||0),correct:Math.max(0,Number(p.correct)||0),wrong:Math.max(0,Number(p.wrong)||0),known:!!p.known,review:!!p.review,last:typeof p.last==='string'?p.last:null,streak:Math.max(0,Number(p.streak)||0),due:typeof p.due==='string'?p.due:null,favorite:!!p.favorite}}state.progress=cleanProgress;state.courseProgress=data.courseProgress&&typeof data.courseProgress==='object'?Object.fromEntries(Object.entries(data.courseProgress).filter(([id,p])=>lessons.some(l=>l.id===id)&&p&&typeof p==='object')):{};state.history=data.history.filter(h=>h&&typeof h==='object'&&Number.isFinite(+h.score)&&Number.isFinite(+h.total)).slice(-300);state.minutesByDay=data.minutesByDay&&typeof data.minutesByDay==='object'?data.minutesByDay:{};state.activities=Array.isArray(data.activities)?data.activities.slice(-100):[];if(data.extraLearning&&typeof data.extraLearning==='object'){extraState={...extraState,...data.extraLearning,examHistory:Array.isArray(data.extraLearning.examHistory)?data.extraLearning.examHistory.slice(-100):[],attempts:Array.isArray(data.extraLearning.attempts)?data.extraLearning.attempts.slice(-200):[]};saveExtra()}if(data.settings){state.theme=['light','dark','system'].includes(data.settings.theme)?data.settings.theme:'light';try{localStorage.setItem('taiwanMandarin_theme_v1',state.theme)}catch(storageError){}state.ui=['zh','en','bi'].includes(data.settings.ui)?data.settings.ui:'zh';state.goal=[5,10,15,20,30,60].includes(+data.settings.goal)?+data.settings.goal:60;state.profile=typeof data.settings.profile==='string'?data.settings.profile:'Learner';state.voice=typeof data.settings.voice==='string'?data.settings.voice:'auto';state.speechRate=normalizeSpeechRate(data.settings.speechRate);state.audioEndpointUrl=typeof data.settings.audioEndpointUrl==='string'?data.settings.audioEndpointUrl:'';state.audioVoiceId=typeof data.settings.audioVoiceId==='string'?data.settings.audioVoiceId:'';if($('audioCloudVoice'))$('audioCloudVoice').value=state.audioVoiceId;if($('speechRateSelect'))$('speechRateSelect').value=String(state.speechRate)}if(data.learningEngine&&typeof data.learningEngine==='object'){learningEngine=normalizeLearningEngine(data.learningEngine);saveLearningEngine()}save();applyTheme();renderI18n();toast(t('import_success'))}catch(err){toast(t('import_error'))}finally{e.target.value=''}});
function resetProgress(){if(!confirm(t('reset_confirm')))return;if(typeof createLearningEngineState==='function'){const keepGoal=state.goal||60;learningEngine=createLearningEngineState();learningEngine.preferences.goalMinutes=keepGoal;saveLearningEngine()}state.progress={};state.courseProgress={};state.history=[];state.minutesByDay={};state.activities=[];extraState={reading:0,grammar:0,listening:0,speaking:0,writing:0,examHistory:[],attempts:[]};saveExtra();save();renderAll();toast(t('reset_done'))}
function renderVoiceListSafe(){renderVoiceList()}

// Learning modules are stored separately and are included in backups.
const EXTRA_KEY='taiwanMandarin_extraLearning_v1';
let extraState={reading:0,grammar:0,listening:0,speaking:0,writing:0,examHistory:[],attempts:[]};
try{const savedExtra=JSON.parse(localStorage.getItem(EXTRA_KEY)||'{}');if(savedExtra&&typeof savedExtra==='object')extraState={...extraState,...savedExtra,examHistory:Array.isArray(savedExtra.examHistory)?savedExtra.examHistory.slice(-100):[],attempts:Array.isArray(savedExtra.attempts)?savedExtra.attempts.slice(-200):[]}}catch(e){}
function saveExtra(){try{localStorage.setItem(EXTRA_KEY,JSON.stringify(extraState))}catch(e){}}
function extraFeedback(id,msg,ok){const el=$(id);if(!el)return;el.textContent=msg;el.classList.toggle('error',!ok)}
function checkExtra(module,answer){
 const correct={reading:'a',grammar:'b',listening:'a'}[module];
 const ok=answer===correct;extraState[module]=(extraState[module]||0)+1;
 extraState.attempts.unshift({module,correct:ok,date:today()});extraState.attempts=extraState.attempts.slice(0,200);saveExtra();
 const msg=ok?({reading:'Correct! The text says the speaker bought a rice ball and soy milk. / 答對了！',grammar:'Correct! 「我想要茶」是自然的語序。/ 答對了！',listening:'Correct! The sentence asks where the MRT station is. / 答對了！'}[module]):({reading:'Not quite. Read the first two sentences again. / 再讀一次短文。',grammar:'Not quite. The usual order is subject + 想要 + object. / 再試一次。',listening:'Not quite. Listen again and try another answer. / 再聽一次。'}[module]);
 extraFeedback(module+'Feedback',msg,ok);
}

function playListening(){speakMandarin('請問，捷運站在哪裡？')}
function toggleListeningHint(){const el=$('listeningHint');if(el)el.hidden=!el.hidden}
function startSpeechCheck(){
 const out=$('speechFeedback');const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
 if(!SR){out.textContent='此瀏覽器不支援語音辨識。請跟讀範例；程式不會假裝評分你的聲調。 / Speech recognition is not supported here.';out.classList.add('error');return}
 try{const rec=new SR();rec.lang='zh-TW';rec.interimResults=false;rec.maxAlternatives=1;out.textContent='正在聆聽，請說出句子… / Listening—say the sentence now.';out.classList.remove('error');rec.onresult=e=>{const spoken=e.results?.[0]?.[0]?.transcript||'';out.textContent='辨識結果 / Recognized: '+spoken+'。請自行比較範例；此結果不是聲調評分。';extraState.speaking++;extraState.attempts.unshift({module:'speaking',recognized:spoken,date:today()});saveExtra()};rec.onerror=()=>{out.textContent='未能取得語音結果。請檢查麥克風權限，或改用跟讀練習。';out.classList.add('error')};rec.start()}catch(e){out.textContent='無法啟動語音辨識，請改用跟讀練習。';out.classList.add('error')}
}
function checkWriting(){
 const input=$('writingAnswer');const val=(input?.value||'').normalize('NFC').replace(/[。！!？?，,\s]/g,'');const ok=val==='我想要一杯水';
 extraState.writing++;extraState.attempts.unshift({module:'writing',correct:ok,date:today()});extraState.attempts=extraState.attempts.slice(0,200);saveExtra();
 extraFeedback('writingFeedback',ok?'很好！句子自然且意思正確。 / Good sentence!':'還差一點。參考語序：我 + 想要 + 一杯水。/ Hint: subject + 想要 + object.',ok);
}
