let examAnswers=[];
function startExtraExam(){examAnswers=Array(examQuestions.length).fill(null);renderExamQuestions()}
function renderExamQuestions(){
 const area=$('examArea');if(!area)return;
 area.innerHTML=examQuestions.map((q,i)=>`<div class="exam-question"><b>${i+1}. ${safe(q.q)}</b><div class="exam-options">${q.opts.map((o,j)=>`<button class="${examAnswers[i]===j?'selected':''}" onclick="setExamAnswer(${i},${j})">${String.fromCharCode(65+j)}. ${safe(o)}</button>`).join('')}</div></div>`).join('')+`<div class="action-row" style="margin-top:18px"><button class="btn btn-green" onclick="submitExtraExam()">提交測驗 Submit</button><button class="btn btn-line" onclick="startExtraExam()">重新開始 Restart</button></div><div id="examFeedback" class="feedback" aria-live="polite"></div>`;
}
function setExamAnswer(i,j){examAnswers[i]=j;renderExamQuestions()}
function submitExtraExam(){
 if(examAnswers.some(a=>a===null)){const el=$('examFeedback');if(el){el.textContent='請先回答所有題目。 Please answer every question.';el.classList.add('error')}return}
 const score=examAnswers.reduce((n,a,i)=>n+(a===examQuestions[i].a?1:0),0);const result={score,total:examQuestions.length,date:new Date().toISOString()};extraState.examHistory.unshift(result);extraState.examHistory=extraState.examHistory.slice(0,100);extraState.attempts.unshift({module:'exam',correct:score,total:examQuestions.length,date:today()});saveExtra();
 const el=$('examFeedback');if(el){el.classList.remove('error');el.textContent=`測驗完成：${score}/${examQuestions.length} (${Math.round(score/examQuestions.length*100)}%). ${score===examQuestions.length?'Excellent!':'Review the missed items and try again.'}`}
}
function renderExtraPage(page){
 setPageTitle(page);
 if(page==='exam'&&$('examArea')&&!$('examArea').dataset.started){$('examArea').dataset.started='0'}
}


function addDays(dateString, days){const d=new Date(dateString+'T12:00:00');d.setDate(d.getDate()+days);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function applyTheme(){const choice=state.theme||'light';const dark=choice==='dark'||(choice==='system'&&window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches);document.body.classList.toggle('dark-theme',!!dark);document.documentElement.style.colorScheme=dark?'dark':'light';const sel=$('themeSelect');if(sel)sel.value=choice;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',dark?'#151b18':'#f6f5f1')}
function startConfiguredQuiz(){state.quizLength=Math.max(5,Math.min(5000,Number($('quizLength')?.value)||10));state.quizMode=$('quizMode')?.value||'mixed';state.quiz=null;startExpandedQuiz()}
function startFlashcards(){const mode=$('flashMode')?.value||'daily';let pool=[];if(mode==='daily'){const duePool=words.filter(w=>{const p=wordProgress(w.id);return !!p.review||!!p.due&&p.due<=today()}).slice().sort((a,b)=>{const pa=wordProgress(a.id),pb=wordProgress(b.id);return Number(!!pb.review)-Number(!!pa.review)||(pa.due||'9999-99-99').localeCompare(pb.due||'9999-99-99')||(pb.wrong||0)-(pa.wrong||0)});pool=duePool.slice(0,20);const used=new Set(pool.map(w=>w.id));if(pool.length<20){const newPool=words.filter(w=>{const p=wordProgress(w.id);return !p.seen&&!p.known&&!used.has(w.id)}).slice().sort((a,b)=>b.priorityScore-a.priorityScore||b.utilityScore-a.utilityScore||b.commonScore-a.commonScore);pool.push(...newPool.slice(0,20-pool.length));}}else{pool=words.filter(w=>{const p=wordProgress(w.id);if(mode==='due')return !!p.due&&p.due<=today()||p.review;if(mode==='favorites')return !!p.favorite;if(mode==='unseen')return !p.seen&&!p.known;if(mode==='wrong')return !!p.review||p.wrong>0;return true});pool=pool.slice().sort((a,b)=>{const pa=wordProgress(a.id),pb=wordProgress(b.id);return (pa.due||'9999-99-99').localeCompare(pb.due||'9999-99-99')});for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}}flashQueue=pool;flashIndex=0;flashRevealed=false;renderFlashcard()}
let flashQueue=[],flashIndex=0,flashRevealed=false;
function renderFlashcard(){const box=$('flashCard');if(!box)return;const due=words.filter(w=>{const p=wordProgress(w.id);return p.review||(p.due&&p.due<=today())}).length;const badge=$('flashDueBadge');if(badge)badge.textContent=`${t('flash_due_badge')}: ${due}`;if(!flashQueue.length){box.innerHTML=`<div class="flash-empty"><div class="emoji">🎉</div><h3>${t('flash_empty_title')}</h3><p class="muted">${t('flash_empty_desc')}</p><button class="btn btn-green" onclick="setFlashModeAll()">${t('flash_all_action')}</button></div>`;return}const w=flashQueue[Math.min(flashIndex,flashQueue.length-1)],p=wordProgress(w.id);box.innerHTML=`<div class="quiz-top"><span>${t('flash_step_label')} ${flashIndex+1} / ${flashQueue.length}</span><span>${p.favorite?'★ '+t('flash_favorite_state'):t('flash_favorite_hint')}</span></div><div class="flash-progress"><span style="width:${(flashIndex+1)/flashQueue.length*100}%"></span></div><div class="flash-card-content"><div class="flash-main-word">${safe(w.zh)}</div>${flashRevealed?`<div class="flash-sub">${safe(w.py)}</div><div class="flash-meaning">${safe(w.en)}</div><div class="flash-example"><b>${safe(w.ex)}</b><br><span style="color:var(--green)">${safe(w.expy)}</span><br><span class="muted">${safe(w.exen)}</span><div style="margin-top:12px"><button type="button" class="btn btn-soft sentence-audio-btn" title="${safe(t('example_play'))}" onclick="speakExample('${w.id}')">🔊 ${safe(t('example_play'))}</button></div></div>`:`<p class="muted">${t('flash_recall_hint')}</p><button class="btn btn-green" onclick="revealFlashcard()">${t('flash_reveal_answer')}</button>`}</div><div class="flash-actions">${flashRevealed?`<button class="btn btn-line" onclick="rateFlashcard(1)">${t('flash_again')} · 1 ${t('review_day_unit')}</button><button class="btn btn-soft" onclick="rateFlashcard(3)">${t('flash_familiar')} · 3 ${t('review_day_unit')}</button><button class="btn btn-green" onclick="rateFlashcard(7)">${t('flash_mastered')} · 7 ${t('review_day_unit')}</button>`:`<button class="btn btn-line" onclick="speak('${w.id}')">🔊 ${t('speak')}</button><button class="btn btn-line favorite-btn" onclick="toggleFavorite('${w.id}');renderFlashcard()">${p.favorite?'★ '+t('flash_favorite_state'):'☆ '+t('flash_favorite_button')}</button>`}<button class="btn btn-line" onclick="skipFlashcard()">${t('flash_skip')} →</button></div>`}function revealFlashcard(){flashRevealed=true;renderFlashcard()}
function rateFlashcard(days){if(!flashQueue.length)return;const w=flashQueue[flashIndex],p=wordProgress(w.id);p.seen=(p.seen||0)+1;p.last=today();p.due=addDays(today(),days);p.streak=days===1?0:(p.streak||0)+1;if(days===1){p.review=true;p.known=false}else{p.review=false;if(days>=7)p.known=true}activity({kind:'flashcard',wordId:w.id,days});save();flashIndex++;flashRevealed=false;if(flashIndex>=flashQueue.length){toast(t('flash_cycle_done'));flashQueue=[];flashIndex=0}renderFlashcard();renderStats();renderReview();renderProgress();renderCurriculum()}
function skipFlashcard(){if(!flashQueue.length)return;flashIndex=(flashIndex+1)%flashQueue.length;flashRevealed=false;renderFlashcard()}
function setFlashModeAll(){if($('flashMode'))$('flashMode').value='all';startFlashcards()}
function toggleFavorite(id){const p=wordProgress(id);p.favorite=!p.favorite;save();renderVocab();renderReview();toast(p.favorite?t('favorite_added'):t('favorite_removed'))}
function renderVocab(){if(!$('vocabList'))return;const q=($('vocabSearch').value||'').trim().toLowerCase(),topic=$('topicFilter').value;const list=words.filter(w=>(topic==='all'||w.topic===topic)&&(!q||[w.zh,w.py,w.en,w.ex,w.exen,topicText(w.topic),...SOURCE_HEADERS.map(h=>w.fields[h])].join(' ').toLowerCase().includes(q)));const pages=Math.max(1,Math.ceil(list.length/VOCAB_PAGE_SIZE));vocabPage=Math.max(0,Math.min(vocabPage,pages-1));const from=vocabPage*VOCAB_PAGE_SIZE,shown=list.slice(from,from+VOCAB_PAGE_SIZE);$('vocabCount').textContent=`${list.length.toLocaleString()} / ${words.length.toLocaleString()} 詞條`;$('vocabList').innerHTML=shown.length?shown.map(w=>{const p=wordProgress(w.id),f=w.fields,priority=f['學習優先度（公式計算）']??'—',common=f['常用度分數（0–100；新增詞為教學估計）']??'—',difficulty=f['教學難度估計（1易–5難）']??'—',utility=f['日常實用度估計（1–5）']??'—';const allFields=SOURCE_HEADERS.map(h=>{const raw=f[h],v=raw===null||raw===undefined||raw===''?'—':String(raw);const val=h==='COCT來源頁'&&/^https?:\/\//i.test(v)?`<a href="${safe(v)}" target="_blank" rel="noopener noreferrer">${safe(v)}</a>`:safe(v);return `<div class="word-field"><dt>${safe(h)}</dt><dd>${val}</dd></div>`}).join('');return `<article class="vocab-card card"><div class="hanzi">${safe(w.zh)}</div><div style="min-width:0;flex:1"><div class="meaning">${safe(w.en)}</div><div class="pinyin">${safe(w.py)}${f['注音']?' · '+safe(f['注音']):''}</div><div class="example example-with-audio"><span>${safe(w.ex)}</span><button type="button" class="sentence-audio-btn" title="${safe(t('example_play'))}" aria-label="${safe(t('example_play'))}: ${safe(w.zh)}" onclick="speakExample('${w.id}')">🔊 ${safe(t('example_play'))}</button></div><div class="example" style="margin-top:3px">${safe(w.exen)}</div><div class="vocab-meta">${safe(w.topic)} · 優先度 ${safe(priority)} · 常用度 ${safe(common)} · 難度 ${safe(difficulty)}/5 · 實用度 ${safe(utility)}/5<br>平台建議順序：${safe(CURRICULUM_STAGES[w.courseStage]?.name||'準備起步')}（非官方級別） · 狀態：${safe(learningStatus(p))}<br>${p.seen||0} 次練習 · ${p.due?'下次複習 '+safe(p.due):'尚未排定複習'}</div><details class="word-details"><summary>查看完整 Excel 資料（19 欄）</summary><dl class="word-fields">${allFields}</dl></details></div><div class="vocab-actions"><button class="round-btn" title="播放發音" aria-label="播放${safe(w.zh)}的發音" onclick="speak('${w.id}')">🔊</button><button class="round-btn favorite-btn" title="收藏" aria-label="收藏${safe(w.zh)}" onclick="toggleFavorite('${w.id}')">${p.favorite?'★':'☆'}</button><button class="round-btn" title="標記熟悉" aria-label="標記${safe(w.zh)}為熟悉" onclick="toggleKnown('${w.id}')">${p.known?'✓':'＋'}</button></div></article>`}).join(''):`<div class="card empty" style="grid-column:1/-1">${t('no_results')}</div>`;const pg=$('vocabPagination');if(pg)pg.innerHTML=list.length?`<button class="btn btn-line" onclick="changeVocabPage(-1)" ${vocabPage===0?'disabled':''}>← 上一頁</button><span>第 ${vocabPage+1} / ${pages} 頁 · 顯示 ${from+1}–${Math.min(from+shown.length,list.length)} / ${list.length}</span><button class="btn btn-line" onclick="changeVocabPage(1)" ${vocabPage>=pages-1?'disabled':''}>下一頁 →</button>`:''}
function renderReview(){const list=words.filter(w=>{const p=wordProgress(w.id);return !!p.review||(!!p.due&&p.due<=today())});$('reviewCount').textContent=list.length;$('reviewList').innerHTML=list.length?list.map(w=>{const p=wordProgress(w.id);return `<div class="word-row"><div class="hanzi">${safe(w.zh)}</div><div class="word-info"><b>${safe(w.en)}</b><small>${safe(w.py)} · ${safe(w.ex)}</small><small>${p.due?'下次複習：'+safe(p.due):'建議今天再練一次'} ${p.favorite?'· ★ 已收藏':''}</small></div><span class="pill">錯 ${p.wrong||0} 次</span><button class="round-btn" aria-label="播放發音" onclick="speak('${w.id}')">🔊</button><button class="round-btn" aria-label="加入字卡" onclick="go('flashcards');$('flashMode').value='due';startFlashcards()">↻</button></div>`}).join(''):`<div class="empty">目前沒有到期的複習項目。用字卡學習新單字，系統會安排之後的複習日期。</div>`}
function renderProgress(){if($('extraReadingCount'))$('extraReadingCount').textContent=extraState.reading||0;if($('extraGrammarCount'))$('extraGrammarCount').textContent=extraState.grammar||0;if($('extraListeningCount'))$('extraListeningCount').textContent=extraState.listening||0;if($('extraExamCount'))$('extraExamCount').textContent=extraState.examHistory?.length||0;const list=state.activities.slice(0,12);if($('activityList'))$('activityList').innerHTML=list.length?list.map(a=>`<div class="word-row"><div class="stat-icon">✓</div><div class="word-info"><b>${safe(a.text)}</b><small>${safe(a.date)}</small></div></div>`).join(''):`<div class="empty">${t('no_activity')}</div>`;const chart=$('weeklyChart');if(chart){const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const k=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;days.push({key:k,value:Number(state.minutesByDay[k])||0,label:['日','一','二','三','四','五','六'][d.getDay()]})}const max=Math.max(5,...days.map(d=>d.value));chart.innerHTML=days.map(d=>`<div class="weekly-day" title="${d.key}：${d.value} 分鐘"><strong>${d.value}</strong><div class="weekly-stick" style="--h:${Math.max(4,d.value/max*70)}px"></div><span>${d.label}</span></div>`).join('')}}
function getDateLocal(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
