// 1.0.4: generated 300-item banks for every practice module.
const MODULE_NAMES={reading:'閱讀理解',grammar:'文法句型',listening:'聽力辨識',speaking:'口說跟讀',writing:'中文寫作',exam:'綜合測驗'};
const moduleBanks={}; const moduleSession={};
function shuffledCopy(a){const b=a.slice();for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function makeModuleBank(kind){
 const bank=[]; const base=words.filter(w=>w.zh&&w.py&&w.en&&w.ex&&w.exen);
 if(!base.length)return bank;
 for(let i=0;i<300;i++){
  const w=base[i%base.length], v=Math.floor(i/base.length)%3;
  const distractors=[1,2,3].map(n=>base[(i+n*7+Math.floor(i/base.length)*3)%base.length]).filter(x=>x.id!==w.id);
  const unique=[w,...distractors].filter((x,j,a)=>a.findIndex(y=>y.id===x.id)===j).slice(0,4);
  while(unique.length<4)unique.push(base[(i+unique.length+11)%base.length]);
  let q={id:i+1,word:w,opts:[],answer:0};
  if(kind==='reading'){
   q.title=['閱讀句子，選出正確意思。','讀完情境句，找出英文解釋。','這句華語表達什麼？'][v];q.prompt=w.ex;q.opts=shuffledCopy(unique.map(x=>({label:x.exen,correct:x.id===w.id})));q.answer=q.opts.findIndex(x=>x.correct);
  }else if(kind==='grammar'){
   q.title=['選出符合英文意思的自然華語句子。','根據英文提示，選擇正確語序。','找出意思相符的華語例句。'][v];q.prompt=w.exen;q.opts=shuffledCopy(unique.map(x=>({label:x.ex,correct:x.id===w.id})));q.answer=q.opts.findIndex(x=>x.correct);
  }else if(kind==='listening'){
   q.title=['先播放華語，再選出正確意思。','聽句子並辨識英文含義。','聽完後選擇最符合的解釋。'][v];q.prompt=w.ex;q.opts=shuffledCopy(unique.map(x=>({label:x.exen,correct:x.id===w.id})));q.answer=q.opts.findIndex(x=>x.correct);
  }else if(kind==='speaking'){
   q.title=['聽範例後跟讀，注意聲調。','請清楚朗讀以下華語句子。','先聽標準語音，再跟讀練習。'][v];q.prompt=w.ex;q.pinyin=w.expy;q.meaning=w.exen;q.opts=[];
  }else if(kind==='writing'){
   q.title=['請將英文翻譯成繁體中文。','依英文意思寫出自然的華語句子。','請輸入最符合提示的中文句子。'][v];q.prompt=w.exen;q.expected=w.ex;q.opts=[];
  }else{
   const mode=i%3;
   if(mode===0){q.title='選出中文詞語的英文意思。';q.prompt=w.zh;q.opts=shuffledCopy(unique.map(x=>({label:x.en,correct:x.id===w.id})));}
   else if(mode===1){q.title='選出正確的漢語拼音。';q.prompt=w.zh;q.opts=shuffledCopy(unique.map(x=>({label:x.py,correct:x.id===w.id})));}
   else{q.title='選出與英文句意相符的華語例句。';q.prompt=w.exen;q.opts=shuffledCopy(unique.map(x=>({label:x.ex,correct:x.id===w.id})));}
   q.answer=q.opts.findIndex(x=>x.correct);
  }
  bank.push(q);
 }
 return bank;
}
function buildAllModuleBanks(){['reading','grammar','listening','speaking','writing','exam'].forEach(k=>moduleBanks[k]=makeModuleBank(k));}
function startModule(kind){if(!moduleBanks[kind]||moduleBanks[kind].length!==300)buildAllModuleBanks();moduleSession[kind]={index:0,correct:0,answered:false,selected:-1,finished:false};renderModule(kind)}
function moduleNext(kind){const s=moduleSession[kind];if(!s)return;if(s.index<299){s.index++;s.answered=false;s.selected=-1;renderModule(kind)}else{s.finished=true;renderModule(kind)}}
function answerModule(kind,index){const s=moduleSession[kind],q=moduleBanks[kind]?.[s?.index];if(!s||!q||s.answered)return;s.answered=true;s.selected=index;if(q.opts[index]?.correct)s.correct++;extraState[kind]=(extraState[kind]||0)+1;extraState.attempts.unshift({module:kind,correct:!!q.opts[index]?.correct,date:today()});extraState.attempts=extraState.attempts.slice(0,200);saveExtra();renderModule(kind)}
function submitWritingModule(){const kind='writing',s=moduleSession[kind],q=moduleBanks[kind]?.[s?.index];if(!s||!q||s.answered)return;const val=($('moduleWritingAnswer')?.value||'').normalize('NFC').replace(/[。！!？?，,、\s]/g,'');const expected=(q.expected||'').normalize('NFC').replace(/[。！!？?，,、\s]/g,'');s.answered=true;s.selected=val===expected?0:1;if(s.selected===0)s.correct++;extraState.writing=(extraState.writing||0)+1;extraState.attempts.unshift({module:kind,correct:s.selected===0,date:today()});extraState.attempts=extraState.attempts.slice(0,200);saveExtra();renderModule(kind)}
function renderModule(kind){
 const section=$('view-'+kind);if(!section)return;let card=section.querySelector('.module-bank-card');if(!card){section.querySelectorAll('.extra-card').forEach(x=>x.remove());card=document.createElement('div');card.className='card extra-card module-bank-card';section.appendChild(card)}
 const s=moduleSession[kind],bank=moduleBanks[kind];if(!s||!bank){card.innerHTML='<p>題庫載入中…</p>';return}
 if(s.finished){card.innerHTML=`<div style="text-align:center;padding:25px"><h3>${MODULE_NAMES[kind]}完成！</h3><p>本輪已完成 300 題。答對：${s.correct} 題。</p><div class="bar"><span style="width:${s.correct/300*100}%;background:var(--green)"></span></div><p class="muted">正確率 ${Math.round(s.correct/300*100)}%</p><button class="btn btn-green" onclick="startModule('${kind}')">重新練習 300 題</button></div>`;return}
 const q=bank[s.index];let body='';
 if(kind==='speaking')body=`<div class="reading-text"><b style="font-size:24px">${safe(q.prompt)}</b><br><span class="muted">${safe(q.pinyin||'')}</span><br>${safe(q.meaning||'')}</div><div class="action-row"><button class="btn btn-green" onclick='speakMandarin(${JSON.stringify(q.prompt)})'>🔊 聽範例</button><button class="btn btn-line" onclick="startSpeechCheck()">🎙 試著說</button><button class="btn btn-soft" onclick="completeSpeaking()">完成跟讀</button></div><div id="speechFeedback" class="feedback" aria-live="polite">跟讀後可自行比較；瀏覽器語音辨識不代表聲調評分。</div>`;
 else if(kind==='writing')body=`<p class="reading-text" style="font-size:16px">${safe(q.prompt)}</p><label for="moduleWritingAnswer">你的繁體中文答案</label><input id="moduleWritingAnswer" class="writing-input" placeholder="請輸入中文句子…" autocomplete="off" ${s.answered?'disabled':''}><div class="action-row"><button class="btn btn-green" onclick="submitWritingModule()" ${s.answered?'disabled':''}>檢查答案</button><button class="btn btn-line" onclick='document.getElementById("moduleWritingAnswer").value=${JSON.stringify(q.expected)}'>顯示參考答案</button></div>${s.answered?`<div class="feedback ${s.selected===0?'':'error'}">${s.selected===0?'答對了！':'參考答案：'+safe(q.expected)}</div>`:''}`;
 else body=`<div class="quiz-question"><b>${safe(q.title)}</b><div class="reading-text" style="font-size:20px;margin:16px 0">${kind==='listening'?'🔊 聽力題目（先播放音訊）':kind==='exam'?'綜合題目':'題目'}<br><strong>${kind==='listening'?'（音訊不顯示文字，按播放聆聽）':safe(q.prompt)}</strong></div>${kind==='listening'?`<button class="btn btn-green" onclick='speakMandarin(${JSON.stringify(q.prompt)})'>🔊 播放華語</button>`:''}<div class="answer-grid" style="margin-top:14px">${q.opts.map((o,j)=>`<button class="btn ${s.answered?(o.correct?'btn-green':(j===s.selected?'':'btn-line')):'btn-line'}" onclick="answerModule('${kind}',${j})" ${s.answered?'disabled':''}>${String.fromCharCode(65+j)}. ${safe(o.label)}</button>`).join('')}</div>${s.answered?`<div class="feedback ${q.opts[s.selected]?.correct?'':'error'}">${q.opts[s.selected]?.correct?'答對了！':'再試一次。'} 正確答案：${safe(q.opts[q.answer]?.label||'')}</div>`:''}</div>`;
 card.innerHTML=`<div class="quiz-top"><span>${MODULE_NAMES[kind]} · 第 ${s.index+1} / 300 題</span><span>本輪答對 ${s.correct} 題</span></div><div class="step-line"><span style="width:${(s.index+1)/300*100}%"></span></div><h3>${safe(q.title)}</h3>${body}<div class="quiz-footer"><span class="muted tiny">題庫共 300 題</span><button class="btn btn-green" onclick="moduleNext('${kind}')" ${!s.answered?'disabled':''}>${s.index===299?'完成 300 題':'下一題 →'}</button></div>`;
}

function completeSpeaking(){const s=moduleSession.speaking;if(!s||s.answered)return;s.answered=true;extraState.speaking=(extraState.speaking||0)+1;extraState.attempts.unshift({module:'speaking',date:today()});extraState.attempts=extraState.attempts.slice(0,200);saveExtra();renderModule('speaking')}
function startSpeechCheck(){const out=$('speechFeedback');const SR=window.SpeechRecognition||window.webkitSpeechRecognition;const q=moduleBanks.speaking?.[moduleSession.speaking?.index];if(!SR){if(out)out.textContent='此瀏覽器不支援語音辨識。請聽範例後自行跟讀。';return}try{const rec=new SR();rec.lang='zh-TW';rec.interimResults=false;rec.maxAlternatives=1;if(out)out.textContent='正在聆聽，請說出本題句子…';rec.onresult=e=>{const spoken=e.results?.[0]?.[0]?.transcript||'';if(out)out.textContent='辨識結果：'+spoken+'。請自行比較範例；此結果不是聲調評分。'};rec.onerror=()=>{if(out)out.textContent='未能取得語音結果，請檢查麥克風權限或改用跟讀。'};rec.start()}catch(e){if(out)out.textContent='無法啟動語音辨識，請改用跟讀練習。'}}


const articleLibrary = [
 {id:'a1',level:'初級 A1',topic:'飲食',title:'台灣人的早餐',en:'Breakfast in Taiwan',body:'早上七點，怡君走進住家附近的早餐店。她點了一份蛋餅和一杯豆漿。店員問：「要在這裡吃，還是外帶？」怡君說：「我要外帶，謝謝。」她帶著早餐去上班。',translation:'At seven in the morning, Yi-jun walks into a breakfast shop near her home. She orders an egg pancake and a cup of soy milk. The staff asks, “For here or to go?” Yi-jun says, “To go, thank you.” She takes her breakfast to work.',words:[['早餐','zǎocān','breakfast'],['附近','fùjìn','nearby'],['蛋餅','dànbǐng','egg pancake'],['豆漿','dòujiāng','soy milk'],['外帶','wàidài','take away']],question:'怡君點了什麼？',answer:'一份蛋餅和一杯豆漿。'},
 {id:'a2',level:'初級 A1',topic:'交通',title:'第一次搭捷運',en:'Taking the MRT for the first time',body:'馬克今天要去台北車站。他先看地圖，再買一張單程票。月台上有很多人。列車到了以後，他先讓下車的人出去，再走進車廂。',translation:'Mark is going to Taipei Main Station today. He checks the map first, then buys a one-way ticket. There are many people on the platform. When the train arrives, he lets passengers get off before entering the train.',words:[['車站','chēzhàn','station'],['地圖','dìtú','map'],['單程票','dānchéng piào','one-way ticket'],['月台','yuètái','platform'],['車廂','chēxiāng','train carriage']],question:'馬克先做什麼？',answer:'他先看地圖。'},
 {id:'a3',level:'初級 A1',topic:'購物',title:'便利商店買東西',en:'Shopping at a convenience store',body:'安娜下課後去便利商店。她買了一瓶水、一個飯糰，還用店裡的機器繳電話費。結帳時，店員問她要不要購物袋。安娜說：「不用了，謝謝。」',translation:'After class, Anna goes to a convenience store. She buys a bottle of water and a rice ball, and uses the store machine to pay her phone bill. At checkout, the clerk asks if she needs a shopping bag. Anna says, “No, thank you.”',words:[['下課','xiàkè','after class'],['飯糰','fàntuán','rice ball'],['機器','jīqì','machine'],['電話費','diànhuà fèi','phone bill'],['結帳','jiézhàng','check out / pay']],question:'安娜用機器做什麼？',answer:'她用機器繳電話費。'},
 {id:'a4',level:'初級 A1',topic:'生活',title:'跟新朋友自我介紹',en:'Introducing yourself to a new friend',body:'語言交換活動開始了。大衛說：「你好，我叫大衛，來自加拿大。我在台灣住了三個月，現在學中文。」小美笑著說：「很高興認識你！如果你需要幫忙，可以問我。」',translation:'The language exchange begins. David says, “Hello, my name is David. I’m from Canada. I’ve lived in Taiwan for three months, and I’m learning Chinese now.” Xiao-mei smiles and says, “Nice to meet you! If you need help, you can ask me.”',words:[['語言交換','yǔyán jiāohuàn','language exchange'],['來自','láizì','to come from'],['三個月','sān ge yuè','three months'],['認識','rènshi','to meet / know'],['幫忙','bāngmáng','to help']],question:'大衛來自哪裡？',answer:'他來自加拿大。'},
 {id:'a5',level:'初級 A2',topic:'租屋',title:'找一間房子',en:'Looking for a room',body:'莉娜想在學校附近租房子。她在網路上看到一間套房，房租每個月一萬二千元，水電費另外計算。她約房東星期六看房，也想確認房間有沒有洗衣機。',translation:'Lina wants to rent a place near her school. Online, she finds a studio apartment with monthly rent of NT$12,000; utilities are calculated separately. She arranges to view it with the landlord on Saturday and wants to check whether there is a washing machine.',words:[['租房子','zū fángzi','rent a place'],['套房','tàofáng','studio apartment'],['房租','fángzū','rent'],['水電費','shuǐdiàn fèi','utilities'],['房東','fángdōng','landlord']],question:'莉娜想確認房間裡有什麼？',answer:'她想確認有沒有洗衣機。'},
 {id:'a6',level:'初級 A2',topic:'健康',title:'去診所看醫生',en:'Visiting a clinic',body:'志明昨天開始咳嗽，今天早上還有一點發燒。他去附近的診所掛號，等了一會兒才看醫生。醫生請他多喝水、好好休息，如果症狀變嚴重就要再回診。',translation:'Zhi-ming started coughing yesterday and had a slight fever this morning. He registers at a nearby clinic and waits a while before seeing the doctor. The doctor tells him to drink more water and rest, and to return if his symptoms get worse.',words:[['咳嗽','késòu','to cough'],['發燒','fāshāo','to have a fever'],['診所','zhěnsuǒ','clinic'],['掛號','guàhào','register for an appointment'],['休息','xiūxí','rest']],question:'醫生請志明做什麼？',answer:'多喝水、好好休息。'},
 {id:'a7',level:'初級 A2',topic:'文化',title:'週末逛夜市',en:'Visiting a night market',body:'星期六晚上，朋友帶艾瑪去夜市。那裡有很多小吃和遊戲攤位。他們先買了地瓜球和臭豆腐，再玩了套圈圈。人很多，但是氣氛很熱鬧。艾瑪說，她下次還想再來。',translation:'On Saturday evening, a friend takes Emma to a night market. There are lots of snacks and game stalls. They buy sweet potato balls and stinky tofu, then play a ring-toss game. It is crowded but lively. Emma says she wants to come again.',words:[['夜市','yèshì','night market'],['小吃','xiǎochī','snacks'],['攤位','tānwèi','stall'],['套圈圈','tào quānquān','ring toss'],['熱鬧','rènào','lively']],question:'艾瑪覺得夜市怎麼樣？',answer:'人很多，但是氣氛很熱鬧。'},
 {id:'a8',level:'初級 A2',topic:'工作',title:'上班第一天',en:'The first day at work',body:'今天是俊豪到新公司上班的第一天。主管帶他認識同事，也介紹公司的工作流程。午餐時，同事邀請他一起去附近吃麵。俊豪有一點緊張，但大家都很親切。',translation:'Today is Jun-hao’s first day at his new company. His manager introduces him to coworkers and explains the workflow. At lunch, a coworker invites him to eat noodles nearby. Jun-hao is a little nervous, but everyone is friendly.',words:[['主管','zhǔguǎn','manager'],['同事','tóngshì','coworker'],['工作流程','gōngzuò liúchéng','workflow'],['邀請','yāoqǐng','to invite'],['親切','qīnqiè','friendly']],question:'午餐時，同事邀請俊豪去哪裡？',answer:'去附近吃麵。'}
];
function renderArticleLibrary(){
 const view=$('view-reading');if(!view)return;
 let box=$('articleLibraryBox');if(!box){box=document.createElement('section');box.id='articleLibraryBox';box.className='card extra-card';view.appendChild(box)}
 box.innerHTML=`<div class="section-head" style="margin-top:0"><div><div class="eyebrow">READING LIBRARY · 閱讀素材庫</div><h2>台灣生活短文</h2><p class="muted tiny">每篇附英文翻譯、生詞、理解題；點選文章即可展開。</p></div><span class="tag">${articleLibrary.length} 篇文章</span></div><div class="filters" style="margin-bottom:16px"><input id="articleSearch" placeholder="搜尋文章或主題…" oninput="filterArticles()"><select id="articleLevel" onchange="filterArticles()"><option value="all">所有程度</option><option>初級 A1</option><option>初級 A2</option></select></div><div id="articleCards" class="lesson-grid">${articleLibrary.map(a=>articleCard(a)).join('')}</div><div id="articleDetail" style="margin-top:18px"></div>`;
}
function articleCard(a){return `<article class="card lesson"><div class="lesson-art art-peach">📖</div><div class="lesson-meta"><span class="tag">${a.level}</span><span class="pill">${a.topic}</span></div><h3 style="margin-top:12px">${a.title}</h3><p>${a.en}</p><button class="btn btn-soft" onclick="openArticle('${a.id}')">閱讀文章 →</button></article>`}
function filterArticles(){const q=($('articleSearch')?.value||'').toLowerCase();const level=$('articleLevel')?.value||'all';const list=articleLibrary.filter(a=>(level==='all'||a.level===level)&&[a.title,a.en,a.topic,a.body].join(' ').toLowerCase().includes(q));$('articleCards').innerHTML=list.map(articleCard).join('')||'<div class="empty">沒有符合條件的文章。</div>'}
function openArticle(id,scrollToDetail=true){const a=articleLibrary.find(x=>x.id===id);if(!a)return;activeArticleId=id;const detail=$('articleDetail');detail.innerHTML=`<article class="card" style="background:#fbfaf7"><div class="card-heading"><div><span class="tag">${a.level} · ${a.topic}</span><h2 style="margin:12px 0 4px">${a.title}</h2><p class="muted">${a.en}</p></div><button class="btn btn-line" onclick="document.getElementById('articleDetail').innerHTML=''">關閉 ✕</button></div><p class="reading-text" style="font-size:18px;line-height:2;margin-top:22px">${a.body}</p><details style="margin:12px 0"><summary style="cursor:pointer;font-weight:700">英文翻譯 · English translation</summary><p class="reading-text">${a.translation}</p></details><h3>生詞 Vocabulary</h3><div class="vocab-list">${a.words.map(w=>`<div class="card vocab-card"><div class="hanzi">${w[0]}</div><div><div class="pinyin">${w[1]}</div><div class="meaning">${w[2]}</div></div><button class="round-btn" onclick='speakMandarin(${JSON.stringify(w[0])})'>🔊</button></div>`).join('')}</div><div class="example-box"><b>閱讀理解 · Comprehension</b><p>${a.question}</p><button class="btn btn-soft" onclick="this.nextElementSibling.hidden=false">查看答案</button><p hidden>${a.answer}</p></div><button class="btn btn-green" onclick="markArticleRead('${a.id}')">完成閱讀 ✓</button></article>`;if(scrollToDetail)detail.scrollIntoView({behavior:'smooth',block:'start'})}
function closeArticle(){activeArticleId=null;if($('articleDetail'))$('articleDetail').innerHTML=''}
function markArticleRead(id){const a=articleLibrary.find(x=>x.id===id);if(!a)return;extraState.reading=(extraState.reading||0)+1;extraState.attempts.unshift({module:'reading',date:today(),article:id});extraState.attempts=extraState.attempts.slice(0,200);saveExtra();toast('已記錄閱讀：'+a.title)}

