function startQuiz(reviewOnly=false){
 const pool=reviewOnly?words.filter(w=>{const p=wordProgress(w.id);return !!p.review||!!(p.due&&p.due<=today())}):words.slice();
 if(!pool.length){state.quiz={pool:[],index:0,questions:[],answers:[],reviewOnly};renderQuiz();return}
 const n=Math.max(1,Math.min(words.length,Number(state.quizLength)||10));const types=['en','py','zh'];const questions=[];
 for(let i=0;i<n;i++){const w=pool[i%pool.length],type=(!state.quizMode||state.quizMode==='mixed')?types[i%3]:state.quizMode;let distractors=words.filter(x=>x.id!==w.id).sort(()=>Math.random()-.5).slice(0,3);while(distractors.length<3)distractors.push(w);const choices=shuffledCopy([w,...distractors]);questions.push({id:w.id,type,choices:choices.map(x=>({id:x.id,label:type==='en'?x.en:type==='py'?x.py:x.zh})),answer:w.id})}
 state.quiz={pool,index:0,questions,answers:[],selected:null,checked:false,reviewOnly};renderQuiz()
}
