window.startModule=startModule;window.completeSpeaking=completeSpeaking;window.moduleNext=moduleNext;window.answerModule=answerModule;window.submitWritingModule=submitWritingModule;window.startExtraExam=startExtraExam;window.renderExamQuestions=renderExamQuestions;window.setExamAnswer=setExamAnswer;window.submitExtraExam=submitExtraExam;window.startQuiz=startQuiz;window.startConfiguredQuiz=startConfiguredQuiz;window.renderExtraPage=renderExtraPage;

