function createLearningEngineState(){return {schema:1,preferences:{goalMinutes:60,vocabMinutes:20,listeningMinutes:20,speakingMinutes:20,newWordsMode:'auto',migratedGoalTo60:true},skillProgress:{},attempts:[],sessions:[],dailySeconds:{},dailySecondsBySkill:{},dailyPlans:{},currentTask:{},activeSession:null};}
function normalizeLearningEngine(raw){
 const base=createLearningEngineState();if(!raw||typeof raw!=='object')return base;
 const out={...base,...raw,schema:1,preferences:{...base.preferences,...(raw.preferences&&typeof raw.preferences==='object'?raw.preferences:{})},skillProgress:{},attempts:Array.isArray(raw.attempts)?raw.attempts.filter(a=>a&&typeof a==='object').slice(-5000):[],sessions:Array.isArray(raw.sessions)?raw.sessions.filter(a=>a&&typeof a==='object').slice(-5000):[],dailySeconds:raw.dailySeconds&&typeof raw.dailySeconds==='object'?{...raw.dailySeconds}:{},dailySecondsBySkill:raw.dailySecondsBySkill&&typeof raw.dailySecondsBySkill==='object'?{...raw.dailySecondsBySkill}:{},dailyPlans:raw.dailyPlans&&typeof raw.dailyPlans==='object'?{...raw.dailyPlans}:{},currentTask:raw.currentTask&&typeof raw.currentTask==='object'?{...raw.currentTask}:{},activeSession:raw.activeSession&&typeof raw.activeSession==='object'?{...raw.activeSession}:null};
 for(const [wordId,skills] of Object.entries(raw.skillProgress||{})){if(!wordId||!skills||typeof skills!=='object')continue;const clean={};for(const skill of LEARNING_SKILLS){const r=skills[skill];if(r&&typeof r==='object')clean[skill]={attempts:Math.max(0,Number(r.attempts)||0),correct:Math.max(0,Number(r.correct)||0),wrong:Math.max(0,Number(r.wrong)||0),repetitions:Math.max(0,Number(r.repetitions)||0),streak:Math.max(0,Number(r.streak)||0),intervalDays:Math.max(0,Number(r.intervalDays)||0),dueDate:typeof r.dueDate==='string'?r.dueDate:null,lastReviewed:typeof r.lastReviewed==='string'?r.lastReviewed:null,lastResult:['again','hard','good','easy'].includes(r.lastResult)?r.lastResult:null};}if(Object.keys(clean).length)out.skillProgress[wordId]=clean;}
 out.preferences.goalMinutes=[5,10,15,20,30,60].includes(Number(out.preferences.goalMinutes))?Number(out.preferences.goalMinutes):60;out.preferences.vocabMinutes=out.preferences.goalMinutes/3;out.preferences.listeningMinutes=out.preferences.goalMinutes/3;out.preferences.speakingMinutes=out.preferences.goalMinutes/3;out.preferences.newWordsMode='auto';
 if(out.activeSession){out.activeSession.elapsedSeconds=Math.max(0,Number(out.activeSession.elapsedSeconds)||0);out.activeSession.runningSince=null;out.activeSession.status='paused';if(!LEARNING_SKILLS.includes(out.activeSession.skill))out.activeSession=null;}
 for(const [date,n] of Object.entries(out.dailySeconds))out.dailySeconds[date]=Math.max(0,Math.min(86400,Number(n)||0));
 return out;
}
let learningEngine=null,learningTicker=null,learningSavePulse=0;
let learningEngineWasStored=false;
try{const raw=localStorage.getItem(LEARNING_ENGINE_STORAGE_KEY);if(raw){learningEngine=normalizeLearningEngine(JSON.parse(raw));learningEngineWasStored=true}}catch(e){}
if(!learningEngine)learningEngine=createLearningEngineState();
if(!learningEngineWasStored){state.goal=60;learningEngine.preferences.migratedGoalTo60=true;}
else if([5,10,15,20,30,60].includes(Number(learningEngine.preferences.goalMinutes))){state.goal=Number(learningEngine.preferences.goalMinutes);}
function saveLearningEngine(){try{localStorage.setItem(LEARNING_ENGINE_STORAGE_KEY,JSON.stringify(learningEngine));}catch(e){console.warn('[learning-engine] Unable to save learning data',e)}}
const _saveBeforeLearning17=save;
save=function(){_saveBeforeLearning17();saveLearningEngine();};
const _todayMinutesBefore17=todayMinutes;
todayMinutes=function(){return _todayMinutesBefore17()+Math.floor((Number(learningEngine.dailySeconds[today()])||0)/60)};
function saveEngineThenRender(){save();renderLearningEngine();renderStats();}
function engineSkillRecord(wordId,skill){if(!learningEngine.skillProgress[wordId])learningEngine.skillProgress[wordId]={};if(!learningEngine.skillProgress[wordId][skill])learningEngine.skillProgress[wordId][skill]={attempts:0,correct:0,wrong:0,repetitions:0,streak:0,intervalDays:0,dueDate:null,lastReviewed:null,lastResult:null};return learningEngine.skillProgress[wordId][skill]}
function engineTodaySkillSeconds(skill){const entry=learningEngine.dailySecondsBySkill[today()];return Math.max(0,Number(entry&&entry[skill])||0)}
function engineSessionElapsed(){const a=learningEngine.activeSession;if(!a)return 0;const delta=a.runningSince?Math.max(0,Math.floor((Date.now()-Number(a.runningSince))/1000)):0;return Math.max(0,Number(a.elapsedSeconds)||0)+delta}
function engineSkillElapsed(skill){let n=engineTodaySkillSeconds(skill);const a=learningEngine.activeSession;if(a&&a.skill===skill)n+=engineSessionElapsed();return Math.min(engineTargetSeconds(),n)}
function engineFmtTime(seconds){const n=Math.max(0,Math.floor(seconds));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function engineTargetSeconds(){return Math.max(60,Math.round((Number(state.goal)||60)*20));}
function engineBlockMinutes(){return Math.max(1,Math.round((Number(state.goal)||60)/3));}
function engineRemainingSeconds(skill){return Math.max(0,engineTargetSeconds()-engineSkillElapsed(skill))}
function dueWordsForSkill(skill){return words.filter(w=>{const r=learningEngine.skillProgress[w.id]?.[skill];if(r&&r.dueDate&&r.dueDate<=today())return true;if(skill==='vocab'){const p=wordProgress(w.id);return !!p.review||!!(p.due&&p.due<=today())}return false}).sort((a,b)=>{const ra=learningEngine.skillProgress[a.id]?.[skill],rb=learningEngine.skillProgress[b.id]?.[skill],pa=wordProgress(a.id),pb=wordProgress(b.id);const da=ra?.dueDate||pa.due||'9999-99-99',db=rb?.dueDate||pb.due||'9999-99-99';return da.localeCompare(db)||(pb.wrong||0)-(pa.wrong||0)||b.priorityScore-a.priorityScore})}
function engineUnassessedWords(skill){return words.filter(w=>!learningEngine.skillProgress[w.id]?.[skill]?.lastReviewed).sort((a,b)=>b.priorityScore-a.priorityScore||b.utilityScore-a.utilityScore||b.commonScore-a.commonScore)}
function engineChooseWord(skill){const due=dueWordsForSkill(skill);if(due.length)return due[0];const fresh=engineUnassessedWords(skill);if(fresh.length)return fresh[0];const candidates=words.slice().sort((a,b)=>{const ra=learningEngine.skillProgress[a.id]?.[skill]||{},rb=learningEngine.skillProgress[b.id]?.[skill]||{};const wa=(ra.wrong||0)-((ra.correct||0)*.25),wb=(rb.wrong||0)-((rb.correct||0)*.25);return wb-wa||((ra.dueDate||'9999-99-99').localeCompare(rb.dueDate||'9999-99-99'))||b.priorityScore-a.priorityScore});return candidates[0]||null}
function engineCurrentTask(skill){const word=engineChooseWord(skill);if(!word)return null;let cur=learningEngine.currentTask[skill];if(!cur||cur.wordId!==word.id){cur={wordId:word.id,shownAt:Date.now(),revealed:false};learningEngine.currentTask[skill]=cur;saveLearningEngine()}return {word,task:cur}}
function engineSetRevealed(skill){const c=learningEngine.currentTask[skill];if(c)c.revealed=true;renderLearningEngine()}
function engineMedian(nums,fallback,min,max){const list=nums.filter(n=>Number.isFinite(n)&&n>0).slice().sort((a,b)=>a-b);if(list.length<3)return fallback;const mid=Math.floor(list.length/2),v=list.length%2?list[mid]:(list[mid-1]+list[mid])/2;return Math.max(min,Math.min(max,v))}
function engineAvgSeconds(isNew){const vals=learningEngine.attempts.filter(a=>a.skill==='vocab'&&a.isNewWord===isNew&&a.result!=='again'&&Number(a.responseSeconds)>0).slice(- (isNew?10:20)).map(a=>a.responseSeconds);return engineMedian(vals,isNew?90:30,isNew?45:15,isNew?180:90)}
function engineReviewStats(){const dueWords=dueWordsForSkill('vocab'),due=dueWords.length,newCandidates=engineUnassessedWords('vocab'),newSeconds=engineAvgSeconds(true),reviewSeconds=engineAvgSeconds(false),blockSeconds=engineBlockMinutes()*60,remaining=Math.max(0,blockSeconds-due*reviewSeconds),newCount=Math.min(newCandidates.length,Math.floor(remaining/newSeconds));return {due,newCount,newSeconds,reviewSeconds,blockSeconds,remainingSeconds:remaining,newWordIds:newCandidates.slice(0,newCount).map(w=>w.id),dueWordIds:dueWords.map(w=>w.id)}}
function engineRefreshPlan(){const d=engineReviewStats(),block=engineBlockMinutes(),goal=Number(state.goal)||60;const plan={date:today(),goalMinutes:goal,blocks:{vocab:block,listening:block,speaking:block},dueCount:d.due,newWordCount:d.newCount,newWordIds:d.newWordIds,dueWordIds:d.dueWordIds,generatedAt:new Date().toISOString()};learningEngine.dailyPlans[today()]=plan;const old=Object.keys(learningEngine.dailyPlans).sort();for(const k of old.slice(0,Math.max(0,old.length-30)))delete learningEngine.dailyPlans[k];return plan}
function engineApplySchedule(wordId,skill,result){const rec=engineSkillRecord(wordId,skill);const intervals=LEARNING_SRS[result]||LEARNING_SRS.good;let days;if(result==='again'){days=1;rec.repetitions=0;rec.streak=0;rec.wrong++;}else{rec.repetitions=(rec.repetitions||0)+1;rec.streak=(rec.streak||0)+1;rec.correct++;const ix=Math.max(0,Math.min(intervals.length-1,rec.repetitions-1));days=intervals[ix];}rec.attempts=(rec.attempts||0)+1;rec.lastReviewed=today();rec.lastResult=result;rec.intervalDays=days;rec.dueDate=addDays(today(),days);return {record:rec,days}}
function engineRecordAnswer(skill,result){if(!LEARNING_SKILLS.includes(skill)||!['again','hard','good','easy'].includes(result))return;const current=engineCurrentTask(skill);if(!current)return;const {word,task}=current;const legacy=wordProgress(word.id);const isNewWord=skill==='vocab'&&(legacy.seen||0)===0&&!legacy.known&&!learningEngine.skillProgress[word.id]?.vocab;const responseSeconds=Math.max(1,Math.min(300,Math.round((Date.now()-(Number(task.shownAt)||Date.now()))/1000)));const scheduled=engineApplySchedule(word.id,skill,result);learningEngine.attempts.push({date:today(),at:new Date().toISOString(),wordId:word.id,skill,result,days:scheduled.days,responseSeconds,isNewWord});learningEngine.attempts=learningEngine.attempts.slice(-5000);learningEngine.currentTask[skill]=null;
 if(skill==='vocab'){legacy.seen=(legacy.seen||0)+1;legacy.last=today();if(result==='again'){legacy.wrong=(legacy.wrong||0)+1;legacy.review=true;legacy.known=false}else{legacy.correct=(legacy.correct||0)+1;legacy.review=false;legacy.due=scheduled.record.dueDate;legacy.streak=scheduled.record.streak||0;if(scheduled.record.repetitions>=4&&result!=='hard')legacy.known=true;}}
 save();renderLearningEngine();renderStats();renderReview();renderProgress();renderCurriculum();const msg=result==='again'?t('learning_again'):result==='hard'?t('learning_hard'):result==='easy'?t('learning_easy'):t('learning_good');toast(`${msg} · ${t('learning_due_date')}: ${scheduled.record.dueDate}`)}
