function enginePlaySample(skill){const current=engineCurrentTask(skill);if(!current)return;speakMandarin(current.word.ex||current.word.zh);}
function engineStartSession(skill){if(!LEARNING_SKILLS.includes(skill))return;let a=learningEngine.activeSession;if(a&&a.skill!==skill){toast(t('learning_start_other'));return}if(engineRemainingSeconds(skill)<=0&&!a){toast(t('learning_block_done'));return}if(!a){a={id:`${today()}-${skill}-${Date.now()}`,date:today(),skill,elapsedSeconds:0,runningSince:Date.now(),status:'running'};learningEngine.activeSession=a}else{a.runningSince=Date.now();a.status='running'}saveLearningEngine();renderLearningEngine();startLearningTicker()}
function enginePauseSession(){const a=learningEngine.activeSession;if(!a||!a.runningSince)return;a.elapsedSeconds=engineSessionElapsed();a.runningSince=null;a.status='paused';saveLearningEngine();renderLearningEngine();}
function engineFinishSession(auto=false){const a=learningEngine.activeSession;if(!a)return;let seconds=engineSessionElapsed();const remaining=Math.max(0,engineTargetSeconds()-engineTodaySkillSeconds(a.skill));seconds=Math.min(seconds,remaining);a.elapsedSeconds=seconds;a.runningSince=null;const duration=Math.max(0,Math.floor(seconds));if(duration>0){learningEngine.sessions.push({id:a.id,date:a.date||today(),skill:a.skill,seconds:duration,finishedAt:new Date().toISOString(),auto:!!auto});learningEngine.sessions=learningEngine.sessions.slice(-5000);learningEngine.dailySeconds[today()]=(Number(learningEngine.dailySeconds[today()])||0)+duration;if(!learningEngine.dailySecondsBySkill[today()])learningEngine.dailySecondsBySkill[today()]={};learningEngine.dailySecondsBySkill[today()][a.skill]=(Number(learningEngine.dailySecondsBySkill[today()][a.skill])||0)+duration;}learningEngine.activeSession=null;save();renderLearningEngine();renderStats();toast(duration>0?t('learning_session_saved'):t('learning_session_too_short'));if(learningTicker){clearInterval(learningTicker);learningTicker=null}}
function startLearningTicker(){if(learningTicker)clearInterval(learningTicker);learningTicker=setInterval(()=>{const a=learningEngine.activeSession;if(!a||!a.runningSince){clearInterval(learningTicker);learningTicker=null;return}const elapsed=engineSessionElapsed(),remaining=engineRemainingSeconds(a.skill);const timer=$(`learningTimer-${a.skill}`);if(timer)timer.textContent=engineFmtTime(elapsed);const label=$('learningActiveLabel');if(label)label.textContent=localizedOption(a.skill==='vocab'?'learning_summary_vocab':a.skill==='listening'?'learning_summary_listening':'learning_summary_speaking');const detail=$('learningActiveDetail');if(detail)detail.textContent=`${t('learning_active')} · ${engineFmtTime(elapsed)}`;const total=engineTodaySkillSeconds(a.skill)+elapsed;const bar=$(`learningProgress-${a.skill}`);if(bar)bar.style.width=Math.min(100,total/engineTargetSeconds()*100)+'%';if(elapsed>0&&elapsed%5===0){a.elapsedSeconds=elapsed;a.runningSince=Date.now();saveLearningEngine()}if(remaining<=0)engineFinishSession(true)},1000)}
function enginePauseOnHidden(){const a=learningEngine.activeSession;if(a&&a.runningSince){enginePauseSession();}}
