function engineTaskMarkup(skill){const current=engineCurrentTask(skill);if(!current)return `<p>${t('learning_no_word')}</p>`;const w=current.word,task=current.task;const rec=learningEngine.skillProgress[w.id]?.[skill];const due=dueWordsForSkill(skill).some(x=>x.id===w.id);const badge=due?t('learning_due_label'):rec&&rec.lastReviewed?t('learning_started_label'):t('learning_new_label');
 if(skill==='vocab')return `<span class="pill">${safe(badge)} · ${safe(topicText(w.topic))}</span><div class="learning-word">${safe(w.zh)}</div><p class="muted tiny">${safe(t('learning_prompt_recall'))}</p>${task.revealed?`<div class="learning-pinyin">${safe(w.py)}${w.fields['注音']?' · '+safe(w.fields['注音']):''}</div><div class="learning-meaning">${safe(w.en)}</div><div class="learning-example"><b>${safe(w.ex)}</b><br>${safe(w.exen)}<div style="margin-top:10px"><button class="btn btn-soft sentence-audio-btn" onclick="speakExample('${w.id}')">🔊 ${safe(t('example_play'))}</button></div></div><div class="learning-task-actions"><button class="btn btn-line" onclick="engineRecordAnswer('vocab','again')">${safe(t('learning_again'))}</button><button class="btn btn-line" onclick="engineRecordAnswer('vocab','hard')">${safe(t('learning_hard'))}</button><button class="btn btn-soft" onclick="engineRecordAnswer('vocab','good')">${safe(t('learning_good'))}</button><button class="btn btn-green" onclick="engineRecordAnswer('vocab','easy')">${safe(t('learning_easy'))}</button></div>`:`<div class="learning-task-actions"><button class="btn btn-green" onclick="engineRevealAnswer('vocab')">${safe(t('learning_reveal'))}</button><button class="btn btn-line" onclick="enginePlaySample('vocab')">🔊 ${safe(t('learning_play_model'))}</button></div>`}`;
 if(skill==='listening')return `<span class="pill">${safe(badge)} · ${safe(topicText(w.topic))}</span><div class="learning-word">♫</div><p class="muted tiny">${safe(t('learning_prompt_listening'))}</p><div class="learning-task-actions"><button class="btn btn-green" onclick="enginePlaySample('listening')">🔊 ${safe(t('learning_play_audio'))}</button><button class="btn btn-line" onclick="engineRevealAnswer('listening')">${safe(t('learning_reveal_transcript'))}</button></div>${task.revealed?`<div class="learning-example"><b>${safe(w.ex||w.zh)}</b><br>${safe(w.exen||w.en)}</div><div class="learning-task-actions"><button class="btn btn-soft" onclick="engineRecordAnswer('listening','good')">${safe(t('learning_understood'))}</button><button class="btn btn-line" onclick="engineRecordAnswer('listening','again')">${safe(t('learning_repeat'))}</button></div>`:''}`;
 return `<span class="pill">${safe(badge)} · ${safe(topicText(w.topic))}</span><div class="learning-word">${safe(w.zh)}</div><div class="learning-pinyin">${safe(w.py)}</div><div class="learning-example">${safe(w.ex)}</div><p class="muted tiny">${safe(t('learning_prompt_speaking'))}</p><div class="learning-task-actions"><button class="btn btn-line" onclick="enginePlaySample('speaking')">🔊 ${safe(t('learning_play_model'))}</button><button class="btn btn-soft" onclick="engineRecordAnswer('speaking','good')">${safe(t('learning_spoke_ok'))}</button><button class="btn btn-line" onclick="engineRecordAnswer('speaking','again')">${safe(t('learning_speaking_again'))}</button></div>`;
}
function renderLearningBlock(skill){const block=$(`learningBlock-${skill}`),controls=$(`learningControls-${skill}`),task=$(`learningTask-${skill}`),timer=$(`learningTimer-${skill}`),bar=$(`learningProgress-${skill}`);if(!block||!controls||!task)return;const active=learningEngine.activeSession,own=active&&active.skill===skill,remaining=engineRemainingSeconds(skill),elapsed=engineTodaySkillSeconds(skill)+(own?engineSessionElapsed():0);block.classList.toggle('learning-session-active',!!(own&&active.runningSince));if(timer)timer.textContent=engineFmtTime(own?engineSessionElapsed():0);if(bar)bar.style.width=Math.min(100,elapsed/engineTargetSeconds()*100)+'%';if(remaining<=0&&!own){controls.innerHTML=`<span class="learning-status">${safe(t('learning_completed_label'))}</span>`}else if(own){controls.innerHTML=`<button class="btn btn-line" onclick="enginePauseSession()" ${active.runningSince?'':'disabled'}>${safe(t('learning_pause'))}</button><button class="btn btn-green" onclick="engineFinishSession(false)">${safe(t('learning_finish'))}</button><span class="muted tiny">${safe(active.runningSince?t('learning_active'):t('learning_paused'))}</span>`}else{controls.innerHTML=`<button class="btn btn-green" onclick="engineStartSession('${skill}')">${safe(t('learning_start'))}</button>`}task.innerHTML=engineTaskMarkup(skill)}
