function renderLearningReviewSummary(){const el=$('learningReviewSummary');if(!el)return;el.innerHTML=LEARNING_SKILLS.map(skill=>{const rows=Object.entries(learningEngine.skillProgress).map(([wordId,group])=>({word:words.find(w=>w.id===wordId),r:group&&group[skill]})).filter(x=>x.word&&x.r);const due=rows.filter(x=>x.r.dueDate&&x.r.dueDate<=today()).length;const total=rows.length;const right=rows.reduce((n,x)=>n+(x.r.correct||0),0),wrong=rows.reduce((n,x)=>n+(x.r.wrong||0),0);const mastery=total===0?t('learning_not_assessed'):(rows.some(x=>(x.r.repetitions||0)>=4)&&right>=Math.max(3,wrong*3))?t('learning_mastery_high'):right>wrong?t('learning_mastery_mid'):t('learning_mastery_low');const name=t(skill==='vocab'?'learning_summary_vocab':skill==='listening'?'learning_summary_listening':'learning_summary_speaking');return `<div class="learning-plan-row"><span class="stat-icon">${skill==='vocab'?'▤':skill==='listening'?'♫':'◖'}</span><div class="plan-copy"><b>${safe(name)} · ${safe(mastery)}</b><small>${total} ${safe(t('learning_attempts'))} · ${right} ✓ / ${wrong} ✕ · ${safe(t('learning_due_label'))}: ${due}</small></div><span class="learning-status">${engineFmtTime(engineTodaySkillSeconds(skill))} / ${engineFmtTime(engineTargetSeconds())}</span></div>`}).join('')||`<p class="muted tiny">${safe(t('learning_detail_empty'))}</p>`}
